INSERT INTO sessions (id, user_id, title, started_at, ended_at, page_count, status, is_favorite, is_public, tags, sources, created_at, updated_at) VALUES (1, 1, '고양이와 함께 사는 법 — 음수량, 화장실, 놀이', TIMESTAMP '2026-10-17 17:03:00', TIMESTAMP '2026-10-17 17:42:00', 4, 'COMPLETED', true, true, '["놀이", "화장실", "음수량", "사냥놀이", "벤토나이트"]'::jsonb, '[{"title": "고양이 물 잘 먹이는 법", "url": "https://blog.naver.com/catlover/223001", "excerpt": "고양이 음수량은 체중 1kg 당 하루 약 40~50ml 가 권장된다. 건사료만 먹는 고양이는 물이 부족해지기"}, {"title": "모래 추천 받아요", "url": "https://cafe.naver.com/ilovecat/88120", "excerpt": "벤토나이트 모래는 응고력이 좋아 치우기 쉽지만 먼지가 날 수 있다. 두부 모래는 먼지가 적고 변기에 버릴 수"}, {"title": "실내묘 놀이 루틴", "url": "https://brunch.co.kr/@meowdiary/41", "excerpt": "낚싯대 장난감으로 하루 두 번, 10~15분씩 사냥 놀이를 해 주면 실내묘의 운동 부족과 야간 우다다가 줄어"}]'::jsonb, TIMESTAMP '2026-10-17 17:42:00', TIMESTAMP '2026-10-17 17:42:00');
INSERT INTO summaries (session_id, markdown, essay) VALUES (1, '# 고양이와 함께 사는 법 — 음수량, 화장실, 놀이
INSERT INTO sessions (id, user_id, title, started_at, ended_at, page_count, status, is_favorite, is_public, tags, sources, created_at, updated_at) VALUES (2, 1, '강아지 산책과 훈련 — 산책, 훈련, 사료', TIMESTAMP '2026-10-28 05:10:00', TIMESTAMP '2026-10-28 05:53:00', 6, 'COMPLETED', false, false, '["사료", "산책", "훈련", "포도", "발바닥"]'::jsonb, '[{"title": "강아지 산책 시간 정하기", "url": "https://blog.naver.com/doglog/310442", "excerpt": "소형견은 하루 30분, 활동량이 많은 중대형견은 하루 1~2시간 산책이 권장된다. 산책 시간보다 냄새를 맡게"}, {"title": "여름·겨울 산책 주의", "url": "https://dogpages.tistory.com/57", "excerpt": "한여름 아스팔트는 50도를 넘을 수 있어 발바닥 화상 위험이 크다. 손등을 바닥에 5초 대 보고 뜨거우면 산"}, {"title": "분리불안 고민", "url": "https://cafe.naver.com/dogcafe/50213", "excerpt": "분리불안이 있는 강아지는 외출 준비 행동에 무뎌지게 하는 연습이 효과적이다. 열쇠를 들었다 내려놓기를 반복해"}, {"title": "사료 바꾸는 법", "url": "https://dogpages.tistory.com/62", "excerpt": "사료를 바꿀 때는 7~10일에 걸쳐 새 사료 비율을 25%씩 늘려야 설사 같은 장 트러블을 피할 수 있다."}, {"title": "강아지가 먹으면 안 되는 음식", "url": "https://namu.wiki/w/개/먹이", "excerpt": "포도와 건포도, 초콜릿, 양파, 자일리톨은 소량으로도 강아지에게 위험하다. 먹었다면 바로 동물병원에 연락한다"}]'::jsonb, TIMESTAMP '2026-10-28 05:53:00', TIMESTAMP '2026-10-28 05:53:00');
INSERT INTO summaries (session_id, markdown, essay) VALUES (2, '# 강아지 산책과 훈련 — 산책, 훈련, 사료
INSERT INTO sessions (id, user_id, title, started_at, ended_at, page_count, status, is_favorite, is_public, tags, sources, created_at, updated_at) VALUES (3, 2, '스프링 백엔드 공부 — JPA, 인증, 테스트', TIMESTAMP '2026-10-23 12:26:00', TIMESTAMP '2026-10-23 13:13:00', 6, 'COMPLETED', false, false, '["JPA", "테스트", "인증", "N플러스1", "배치사이즈"]'::jsonb, '[{"title": "Spring Data JPA 쿼리 메서드", "url": "https://docs.spring.io/spring-data/jpa/reference/jpa/query-methods.html", "excerpt": "Spring Data JPA 는 메서드 이름으로 쿼리를 만든다. findByUserIdAndDeletedAt"}, {"title": "JPA N+1 문제 정리", "url": "https://velog.io/@devhan/jpa-n-plus-1", "excerpt": "연관 엔티티를 지연 로딩하면 목록을 조회할 때 쿼리가 N+1 번 나갈 수 있다. 페치 조인이나 EntityG"}, {"title": "JWT vs session", "url": "https://stackoverflow.com/questions/27726066", "excerpt": "JWT 는 서버가 상태를 저장하지 않아 확장에 유리하지만, 즉시 로그아웃 처리가 어렵다. 그래서 만료 시간을"}, {"title": "Spring Boot 테스트", "url": "https://docs.spring.io/spring-boot/reference/testing/index.html", "excerpt": "SpringBootTest 는 전체 컨텍스트를 띄워 느리지만 실제와 가깝다. 컨트롤러만 확인할 때는 Mock"}, {"title": "Testcontainers 로 DB 테스트", "url": "https://velog.io/@devhan/testcontainers", "excerpt": "H2 와 운영 DB 의 문법 차이 때문에 테스트는 통과하고 운영에서 깨지는 일이 있다. Testcontain"}]'::jsonb, TIMESTAMP '2026-10-23 13:13:00', TIMESTAMP '2026-10-23 13:13:00');
INSERT INTO summaries (session_id, markdown, essay) VALUES (3, '# 스프링 백엔드 공부 — JPA, 인증, 테스트
INSERT INTO sessions (id, user_id, title, started_at, ended_at, page_count, status, is_favorite, is_public, tags, sources, created_at, updated_at) VALUES (4, 3, 'KBO 야구 보는 법 — 타격지표, 투수, 직관', TIMESTAMP '2026-10-22 14:38:00', TIMESTAMP '2026-10-22 15:47:00', 7, 'COMPLETED', false, false, '["타격지표", "투수", "직관", "WAR", "타격왕"]'::jsonb, '[{"title": "OPS 로 보는 타자", "url": "https://sports.news.naver.com/kbaseball/news/read?oid=001&aid=0014", "excerpt": "OPS 는 출루율과 장타율을 더한 값으로, 0.900 을 넘으면 리그 정상급 타자로 본다. 타율보다 득점 기"}, {"title": "올해 타격왕 경쟁", "url": "https://www.yna.co.kr/view/AKR20261012000100007", "excerpt": "타격왕은 규정 타석(경기 수 × 3.1)을 채운 타자 중 타율이 가장 높은 선수에게 돌아간다. 막판 결장으로"}, {"title": "WAR 이란", "url": "https://namu.wiki/w/WAR", "excerpt": "WAR 은 대체 선수보다 팀 승리를 몇 번 더 만들었는지 나타낸다. 포지션과 구장 차이를 보정해서 선수끼리 "}, {"title": "선발 이닝 수 논쟁", "url": "https://mlbpark.donga.com/mp/b.php?b=kbotown&id=2026101500", "excerpt": "선발 투수가 6이닝 이상을 꾸준히 던져 주면 불펜 소모가 줄어 시즌 후반 순위 싸움에서 큰 차이가 난다."}, {"title": "피치클록 도입 효과", "url": "https://www.chosun.com/sports/baseball/2026/10/14/", "excerpt": "피치 클록 도입 뒤 경기 시간이 평균 20분 가까이 줄었다. 투수는 주자가 없을 때 정해진 시간 안에 투구해"}, {"title": "잠실 직관 좌석 추천", "url": "https://blog.naver.com/ballpark/223777", "excerpt": "잠실은 1루가 홈팀 응원석인 날이 많다. 응원을 즐기려면 내야 응원석, 경기를 편하게 보려면 중앙 테이블석이"}, {"title": "야구장 먹거리", "url": "https://cafe.naver.com/kbofan/301122", "excerpt": "야구장 먹거리는 경기 시작 전에 사 두는 게 좋다. 5회 이후엔 줄이 길어져 이닝을 놓치기 쉽다."}]'::jsonb, TIMESTAMP '2026-10-22 15:47:00', TIMESTAMP '2026-10-22 15:47:00');
INSERT INTO summaries (session_id, markdown, essay) VALUES (4, '# KBO 야구 보는 법 — 타격지표, 투수, 직관
INSERT INTO sessions (id, user_id, title, started_at, ended_at, page_count, status, is_favorite, is_public, tags, sources, created_at, updated_at) VALUES (5, 1, '겨울 준비와 여행 — 난방비, 스키, 건강', TIMESTAMP '2026-10-19 21:36:00', TIMESTAMP '2026-10-19 22:22:00', 6, 'COMPLETED', false, false, '["난방비", "스키", "건강", "초보코스", "가습"]'::jsonb, '[{"title": "난방비 아끼는 법", "url": "https://www.hankyung.com/article/2026101820001", "excerpt": "보일러를 완전히 끄기보다 외출 모드로 두는 편이 난방비가 덜 든다. 다시 데우는 데 드는 에너지가 더 크기 "}, {"title": "스키장 처음 갈 때", "url": "https://snowtrip.tistory.com/12", "excerpt": "스키를 처음 탄다면 첫날은 강습을 받고 초보 코스에서 멈추는 법부터 익히는 것이 안전하다. 리프트 시즌권보다"}, {"title": "겨울철 건조증", "url": "https://health.chosun.com/site/data/html_dir/2026/10/20/", "excerpt": "겨울철 실내 습도는 40~60% 가 적당하다. 가습기를 쓸 때는 매일 물을 갈고 주 1회 이상 세척해야 세균"}, {"title": "독감 예방접종 시작", "url": "https://www.yna.co.kr/view/AKR20261021000300017", "excerpt": "독감 예방접종은 항체가 생기기까지 2주 정도 걸려 10~11월에 맞는 것이 좋다. 65세 이상과 어린이는 무"}]'::jsonb, TIMESTAMP '2026-10-19 22:22:00', TIMESTAMP '2026-10-19 22:22:00');
INSERT INTO summaries (session_id, markdown, essay) VALUES (5, '# 겨울 준비와 여행 — 난방비, 스키, 건강
