INSERT INTO sessions (id, user_id, title, started_at, ended_at, page_count, status, is_favorite, is_public, tags, sources, created_at, updated_at) VALUES (15, 10, '겨울 준비와 여행 — 건강, 난방비, 스키', TIMESTAMP '2026-10-11 23:48:00', TIMESTAMP '2026-10-12 00:30:00', 6, 'COMPLETED', false, true, '["스키", "난방비", "건강", "방한", "가습"]'::jsonb, '[{"title": "겨울철 건조증", "url": "https://health.chosun.com/site/data/html_dir/2026/10/20/", "excerpt": "겨울철 실내 습도는 40~60% 가 적당하다. 가습기를 쓸 때는 매일 물을 갈고 주 1회 이상 세척해야 세균"}, {"title": "독감 예방접종 시작", "url": "https://www.yna.co.kr/view/AKR20261021000300017", "excerpt": "독감 예방접종은 항체가 생기기까지 2주 정도 걸려 10~11월에 맞는 것이 좋다. 65세 이상과 어린이는 무"}, {"title": "난방비 아끼는 법", "url": "https://www.hankyung.com/article/2026101820001", "excerpt": "보일러를 완전히 끄기보다 외출 모드로 두는 편이 난방비가 덜 든다. 다시 데우는 데 드는 에너지가 더 크기 "}, {"title": "뽁뽁이와 문풍지", "url": "https://blog.naver.com/homecare/224010", "excerpt": "창문에 단열 에어캡을 붙이고 문틈에 문풍지를 대면 실내 온도를 2~3도 지킬 수 있다. 결로가 생기면 자주 "}, {"title": "스키장 처음 갈 때", "url": "https://snowtrip.tistory.com/12", "excerpt": "스키를 처음 탄다면 첫날은 강습을 받고 초보 코스에서 멈추는 법부터 익히는 것이 안전하다. 리프트 시즌권보다"}, {"title": "스키 A자 자세", "url": "https://www.youtube.com/watch?v=skibasic02", "excerpt": "A자 자세는 스키 앞쪽을 모으고 뒤를 벌려 속도를 줄이는 기본 제동 자세다. 무릎을 살짝 굽혀야 넘어지지 않"}]'::jsonb, TIMESTAMP '2026-10-12 00:30:00', TIMESTAMP '2026-10-12 00:30:00');
INSERT INTO summaries (session_id, markdown, essay) VALUES (15, '# 겨울 준비와 여행 — 건강, 난방비, 스키
INSERT INTO sessions (id, user_id, title, started_at, ended_at, page_count, status, is_favorite, is_public, tags, sources, created_at, updated_at) VALUES (16, 11, '고양이와 함께 사는 법 — 음수량, 화장실', TIMESTAMP '2026-10-24 21:14:00', TIMESTAMP '2026-10-24 21:43:00', 3, 'COMPLETED', false, true, '["음수량", "화장실", "신장", "정수기", "화장실개수"]'::jsonb, '[{"title": "고양이 물 잘 먹이는 법", "url": "https://blog.naver.com/catlover/223001", "excerpt": "고양이 음수량은 체중 1kg 당 하루 약 40~50ml 가 권장된다. 건사료만 먹는 고양이는 물이 부족해지기"}, {"title": "고양이 건강 관리", "url": "https://namu.wiki/w/고양이/건강", "excerpt": "물을 적게 마시는 습관이 오래 가면 신장 질환과 방광염 위험이 높아진다. 노령묘는 6개월마다 혈액 검사로 신"}, {"title": "모래 추천 받아요", "url": "https://cafe.naver.com/ilovecat/88120", "excerpt": "화장실 개수는 고양이 수보다 하나 더 많게 두는 것이 기본이다. 여러 마리를 키우면 서로 다른 방에 나눠 두"}]'::jsonb, TIMESTAMP '2026-10-24 21:43:00', TIMESTAMP '2026-10-24 21:43:00');
INSERT INTO summaries (session_id, markdown, essay) VALUES (16, '# 고양이와 함께 사는 법 — 음수량, 화장실
INSERT INTO sessions (id, user_id, title, started_at, ended_at, page_count, status, is_favorite, is_public, tags, sources, created_at, updated_at) VALUES (17, 1, '강아지 산책과 훈련 — 산책, 훈련', TIMESTAMP '2026-10-15 20:49:00', TIMESTAMP '2026-10-15 21:29:00', 4, 'COMPLETED', false, true, '["산책", "훈련", "노즈워크", "분리불안", "산책시간"]'::jsonb, '[{"title": "강아지 산책 시간 정하기", "url": "https://blog.naver.com/doglog/310442", "excerpt": "소형견은 하루 30분, 활동량이 많은 중대형견은 하루 1~2시간 산책이 권장된다. 산책 시간보다 냄새를 맡게"}, {"title": "분리불안 고민", "url": "https://cafe.naver.com/dogcafe/50213", "excerpt": "분리불안이 있는 강아지는 외출 준비 행동에 무뎌지게 하는 연습이 효과적이다. 열쇠를 들었다 내려놓기를 반복해"}]'::jsonb, TIMESTAMP '2026-10-15 21:29:00', TIMESTAMP '2026-10-15 21:29:00');
INSERT INTO summaries (session_id, markdown, essay) VALUES (17, '# 강아지 산책과 훈련 — 산책, 훈련
INSERT INTO sessions (id, user_id, title, started_at, ended_at, page_count, status, is_favorite, is_public, tags, sources, created_at, updated_at) VALUES (18, 12, '스프링 백엔드 공부 — JPA, 인증', TIMESTAMP '2026-10-28 08:45:00', TIMESTAMP '2026-10-28 09:56:00', 4, 'COMPLETED', false, true, '["JPA", "인증", "배치사이즈", "N플러스1", "쿼리메서드"]'::jsonb, '[{"title": "Spring Data JPA 쿼리 메서드", "url": "https://docs.spring.io/spring-data/jpa/reference/jpa/query-methods.html", "excerpt": "Spring Data JPA 는 메서드 이름으로 쿼리를 만든다. findByUserIdAndDeletedAt"}, {"title": "JPA N+1 문제 정리", "url": "https://velog.io/@devhan/jpa-n-plus-1", "excerpt": "연관 엔티티를 지연 로딩하면 목록을 조회할 때 쿼리가 N+1 번 나갈 수 있다. 페치 조인이나 EntityG"}, {"title": "JWT vs session", "url": "https://stackoverflow.com/questions/27726066", "excerpt": "JWT 는 서버가 상태를 저장하지 않아 확장에 유리하지만, 즉시 로그아웃 처리가 어렵다. 그래서 만료 시간을"}]'::jsonb, TIMESTAMP '2026-10-28 09:56:00', TIMESTAMP '2026-10-28 09:56:00');
INSERT INTO summaries (session_id, markdown, essay) VALUES (18, '# 스프링 백엔드 공부 — JPA, 인증
INSERT INTO sessions (id, user_id, title, started_at, ended_at, page_count, status, is_favorite, is_public, tags, sources, created_at, updated_at) VALUES (19, 13, 'KBO 야구 보는 법 — 타격지표, 투수', TIMESTAMP '2026-10-27 05:41:00', TIMESTAMP '2026-10-27 07:01:00', 5, 'COMPLETED', false, true, '["타격지표", "투수", "OPS", "WAR", "피치클록"]'::jsonb, '[{"title": "OPS 로 보는 타자", "url": "https://sports.news.naver.com/kbaseball/news/read?oid=001&aid=0014", "excerpt": "OPS 는 출루율과 장타율을 더한 값으로, 0.900 을 넘으면 리그 정상급 타자로 본다. 타율보다 득점 기"}, {"title": "올해 타격왕 경쟁", "url": "https://www.yna.co.kr/view/AKR20261012000100007", "excerpt": "타격왕은 규정 타석(경기 수 × 3.1)을 채운 타자 중 타율이 가장 높은 선수에게 돌아간다. 막판 결장으로"}, {"title": "WAR 이란", "url": "https://namu.wiki/w/WAR", "excerpt": "WAR 은 대체 선수보다 팀 승리를 몇 번 더 만들었는지 나타낸다. 포지션과 구장 차이를 보정해서 선수끼리 "}, {"title": "선발 이닝 수 논쟁", "url": "https://mlbpark.donga.com/mp/b.php?b=kbotown&id=2026101500", "excerpt": "선발 투수가 6이닝 이상을 꾸준히 던져 주면 불펜 소모가 줄어 시즌 후반 순위 싸움에서 큰 차이가 난다."}, {"title": "피치클록 도입 효과", "url": "https://www.chosun.com/sports/baseball/2026/10/14/", "excerpt": "피치 클록 도입 뒤 경기 시간이 평균 20분 가까이 줄었다. 투수는 주자가 없을 때 정해진 시간 안에 투구해"}]'::jsonb, TIMESTAMP '2026-10-27 07:01:00', TIMESTAMP '2026-10-27 07:01:00');
INSERT INTO summaries (session_id, markdown, essay) VALUES (19, '# KBO 야구 보는 법 — 타격지표, 투수
