ergedFrom": []}], "edges": [{"from": "root:1", "to": "topic:0", "type": "hierarchy", "primary": true, "order": 0}, {"from": "root:1", "to": "topic:1", "type": "hierarchy", "primary": true, "order": 1}, {"from": "root:1", "to": "topic:2", "type": "hierarchy", "primary": true, "order": 2}, {"from": "topic:0", "to": "https://www.hankyung.com/article/2026101820001#uc020c59", "type": "hierarchy", "primary": true, "order": 0}, {"from": "topic:1", "to": "https://snowtrip.tistory.com/12#u874925f", "type": "hierarchy", "primary": true, "order": 0}, {"from": "topic:2", "to": "https://health.chosun.com/site/data/html_dir/2026/10/20/#u3e3e4ac", "type": "hierarchy", "primary": true, "order": 0}, {"from": "topic:2", "to": "https://www.yna.co.kr/view/AKR20261021000300017#u33b8503", "type": "hierarchy", "primary": true, "order": 1}, {"from": "https://www.hankyung.com/article/2026101820001#uc020c59", "to": "https://www.yna.co.kr/view/AKR20261021000300017#u33b8503", "type": "related"}]}'::jsonb, '[{"unitKey": "https://www.hankyung.com/article/2026101820001#uc020c59", "pageId": "https://www.hankyung.com/article/2026101820001", "pid": "uc020c59", "order": 0, "pageTitle": "난방비 아끼는 법", "pageUrl": "https://www.hankyung.com/article/2026101820001", "text": "보일러를 완전히 끄기보다 외출 모드로 두는 편이 난방비가 덜 든다. 다시 데우는 데 드는 에너지가 더 크기 때문이다.", "clusterLabel": "Deep Reading", "score": 3.896, "dwellMs": 14532, "firstSeenAt": "2026-10-19T21:38:00+09:00", "lastSeenAt": "2026-10-19T21:38:14.532000+09:00", "mergedFrom": []}, {"unitKey": "https://snowtrip.tistory.com/12#u874925f", "pageId": "https://snowtrip.tistory.com/12", "pid": "u874925f", "order": 0, "pageTitle": "스키장 처음 갈 때", "pageUrl": "https://snowtrip.tistory.com/12", "text": "스키를 처음 탄다면 첫날은 강습을 받고 초보 코스에서 멈추는 법부터 익히는 것이 안전하다. 리프트 시즌권보다 일일권이 낫다.", "clusterLabel": "Deep Reading", "score": 3.89, "dwellMs": 13421, "firstSeenAt": "2026-10-19T21:40:00+09:00", "lastSeenAt": "2026-10-19T21:40:13.421000+09:00", "mergedFrom": []}, {"unitKey": "https://health.chosun.com/site/data/html_dir/2026/10/20/#u3e3e4ac", "pageId": "https://health.chosun.com/site/data/html_dir/2026/10/20/", "pid": "u3e3e4ac", "order": 0, "pageTitle": "겨울철 건조증", "pageUrl": "https://health.chosun.com/site/data/html_dir/2026/10/20/", "text": "겨울철 실내 습도는 40~60% 가 적당하다. 가습기를 쓸 때는 매일 물을 갈고 주 1회 이상 세척해야 세균 번식을 막는다.", "clusterLabel": "Deep Reading", "score": 3.497, "dwellMs": 19598, "firstSeenAt": "2026-10-19T21:43:00+09:00", "lastSeenAt": "2026-10-19T21:43:19.598000+09:00", "mergedFrom": []}, {"unitKey": "https://www.yna.co.kr/view/AKR20261021000300017#u33b8503", "pageId": "https://www.yna.co.kr/view/AKR20261021000300017", "pid": "u33b8503", "order": 0, "pageTitle": "독감 예방접종 시작", "pageUrl": "https://www.yna.co.kr/view/AKR20261021000300017", "text": "독감 예방접종은 항체가 생기기까지 2주 정도 걸려 10~11월에 맞는 것이 좋다. 65세 이상과 어린이는 무료로 맞을 수 있다.", "clusterLabel": "Reading", "score": 2.254, "dwellMs": 6460, "firstSeenAt": "2026-10-19T21:44:00+09:00", "lastSeenAt": "2026-10-19T21:44:06.460000+09:00", "mergedFrom": []}]'::jsonb, '[{"unitKey": "https://www.hankyung.com/article/2026101820001#uc020c59", "pageId": "https://www.hankyung.com/article/2026101820001", "pid": "uc020c59", "order": 0, "clusterLabel": "Deep Reading", "behaviorScore": 3.896, "finalScore": 3.896, "rank": 1, "dwellMs": 14532, "exposureMs": 29064, "firstSeenAt": "2026-10-19T21:38:00+09:00", "lastSeenAt": "2026-10-19T21:38:14.532000+09:00", "selected": true, "mergedInto": null}, {"unitKey": "https://blog.naver.com/homecare/224010#u868c7b1", "pageId": "https://blog.naver.com/homecare/224010", "pid": "u868c7b1", "order": 0, "clusterLabel": "Scanning", "behaviorScore": 1.045, "finalScore": 1.045, "rank": 7, "dwellMs": 2317, "exposureMs": 4634, "firstSeenAt": "2026-10-19T21:39:00+09:00", "lastSeenAt": "2026-10-19T21:39:02.317000+09:00", "selected": false, "mergedInto": null}, {"unitKey": "https://snowtrip.tistory.com/12#u874925f", "pageId": "https://snowtrip.tistory.com/12", "pid": "u874925f", "order": 0, "clusterLabel": "Deep Re