:0", "to": "https://cafe.naver.com/ilovecat/88120#u6ba03d9", "type": "hierarchy", "primary": true, "order": 1}, {"from": "topic:0", "to": "https://cafe.naver.com/ilovecat/88120#uc87bba4", "type": "hierarchy", "primary": true, "order": 0}, {"from": "topic:1", "to": "https://brunch.co.kr/@meowdiary/41#u40618d0", "type": "hierarchy", "primary": true, "order": 1}, {"from": "topic:1", "to": "https://brunch.co.kr/@meowdiary/41#u2e7f0d0", "type": "hierarchy", "primary": true, "order": 0}, {"from": "https://cafe.naver.com/ilovecat/88120#u6ba03d9", "to": "https://brunch.co.kr/@meowdiary/41#u2e7f0d0", "type": "related"}]}'::jsonb, '[{"unitKey": "https://cafe.naver.com/ilovecat/88120#u6ba03d9", "pageId": "https://cafe.naver.com/ilovecat/88120", "pid": "u6ba03d9", "order": 0, "pageTitle": "모래 추천 받아요", "pageUrl": "https://cafe.naver.com/ilovecat/88120", "text": "벤토나이트 모래는 응고력이 좋아 치우기 쉽지만 먼지가 날 수 있다. 두부 모래는 먼지가 적고 변기에 버릴 수 있다는 장점이 있다.", "clusterLabel": "Reading", "score": 2.538, "dwellMs": 8728, "firstSeenAt": "2026-10-21T21:14:00+09:00", "lastSeenAt": "2026-10-21T21:14:08.728000+09:00", "mergedFrom": []}, {"unitKey": "https://cafe.naver.com/ilovecat/88120#uc87bba4", "pageId": "https://cafe.naver.com/ilovecat/88120", "pid": "uc87bba4", "order": 1, "pageTitle": "모래 추천 받아요", "pageUrl": "https://cafe.naver.com/ilovecat/88120", "text": "화장실 개수는 고양이 수보다 하나 더 많게 두는 것이 기본이다. 여러 마리를 키우면 서로 다른 방에 나눠 두어야 스트레스가 줄어든다.", "clusterLabel": "Deep Reading", "score": 3.703, "dwellMs": 17021, "firstSeenAt": "2026-10-21T21:15:00+09:00", "lastSeenAt": "2026-10-21T21:15:17.021000+09:00", "mergedFrom": []}, {"unitKey": "https://brunch.co.kr/@meowdiary/41#u40618d0", "pageId": "https://brunch.co.kr/@meowdiary/41", "pid": "u40618d0", "order": 0, "pageTitle": "실내묘 놀이 루틴", "pageUrl": "https://brunch.co.kr/@meowdiary/41", "text": "낚싯대 장난감으로 하루 두 번, 10~15분씩 사냥 놀이를 해 주면 실내묘의 운동 부족과 야간 우다다가 줄어든다.", "clusterLabel": "Reading", "score": 2.51, "dwellMs": 6059, "firstSeenAt": "2026-10-21T21:16:00+09:00", "lastSeenAt": "2026-10-21T21:16:06.059000+09:00", "mergedFrom": []}, {"unitKey": "https://brunch.co.kr/@meowdiary/41#u2e7f0d0", "pageId": "https://brunch.co.kr/@meowdiary/41", "pid": "u2e7f0d0", "order": 1, "pageTitle": "실내묘 놀이 루틴", "pageUrl": "https://brunch.co.kr/@meowdiary/41", "text": "고양이는 높은 곳에서 주변을 내려다볼 때 안정감을 느낀다. 캣타워나 벽 선반으로 수직 공간을 만들어 주면 영역 다툼도 줄어든다.", "clusterLabel": "Deep Reading", "score": 3.37, "dwellMs": 11492, "firstSeenAt": "2026-10-21T21:17:00+09:00", "lastSeenAt": "2026-10-21T21:17:11.492000+09:00", "mergedFrom": []}]'::jsonb, '[{"unitKey": "https://cafe.naver.com/ilovecat/88120#u6ba03d9", "pageId": "https://cafe.naver.com/ilovecat/88120", "pid": "u6ba03d9", "order": 0, "clusterLabel": "Reading", "behaviorScore": 2.538, "finalScore": 2.538, "rank": 3, "dwellMs": 8728, "exposureMs": 17456, "firstSeenAt": "2026-10-21T21:14:00+09:00", "lastSeenAt": "2026-10-21T21:14:08.728000+09:00", "selected": true, "mergedInto": null}, {"unitKey": "https://cafe.naver.com/ilovecat/88120#uc87bba4", "pageId": "https://cafe.naver.com/ilovecat/88120", "pid": "uc87bba4", "order": 1, "clusterLabel": "Deep Reading", "behaviorScore": 3.703, "finalScore": 3.703, "rank": 1, "dwellMs": 17021, "exposureMs": 34042, "firstSeenAt": "2026-10-21T21:15:00+09:00", "lastSeenAt": "2026-10-21T21:15:17.021000+09:00", "selected": true, "mergedInto": null}, {"unitKey": "https://brunch.co.kr/@meowdiary/41#u40618d0", "pageId": "https://brunch.co.kr/@meowdiary/41", "pid": "u40618d0", "order": 0, "clusterLabel": "Reading", "behaviorScore": 2.51, "finalScore": 2.51, "rank": 4, "dwellMs": 6059, "exposureMs": 12118, "firstSeenAt": "2026-10-21T21:16:00+09:00", "lastSeenAt": "2026-10-21T21:16:06.059000+09:00", "selected": true, "mergedInto": null}, {"unitKey": "https://brunch.co.kr/@meowdiary/41#u2e7f0d0", "pageId": "https://brunch.co.kr/@meowdiary/41", "pid": "u2e7f0d0", "order": 1, "clusterLabel": "Deep Reading", "behaviorScore": 3.37, "finalScore": 3.37, "rank": 2, "dwellMs": 11492, "exposureMs": 22984, "fi