rgedFrom": []}, {"id": "https://mlbpark.donga.com/mp/b.php?b=kbotown&id=2026101500#u602ea36", "type": "unit", "keyword": "이닝이터", "keywordCandidates": ["이닝이터", "불펜"], "score": 2.729, "childCount": 0, "unitRef": {"pageId": "https://mlbpark.donga.com/mp/b.php?b=kbotown&id=2026101500", "pid": "u602ea36"}, "mergedFrom": []}, {"id": "https://www.chosun.com/sports/baseball/2026/10/14/#u17b1782", "type": "unit", "keyword": "피치클록", "keywordCandidates": ["피치클록", "경기시간"], "score": 3.939, "childCount": 0, "unitRef": {"pageId": "https://www.chosun.com/sports/baseball/2026/10/14/", "pid": "u17b1782"}, "mergedFrom": []}], "edges": [{"from": "root:1", "to": "topic:0", "type": "hierarchy", "primary": true, "order": 2}, {"from": "root:1", "to": "topic:1", "type": "hierarchy", "primary": true, "order": 1}, {"from": "root:1", "to": "topic:2", "type": "hierarchy", "primary": true, "order": 0}, {"from": "topic:0", "to": "https://blog.naver.com/ballpark/223777#u7e8c057", "type": "hierarchy", "primary": true, "order": 0}, {"from": "topic:1", "to": "https://sports.news.naver.com/kbaseball/news/read?oid=001&aid=0014#u5b30ec9", "type": "hierarchy", "primary": true, "order": 1}, {"from": "topic:1", "to": "https://www.yna.co.kr/view/AKR20261012000100007#ue080cb0", "type": "hierarchy", "primary": true, "order": 2}, {"from": "topic:1", "to": "https://namu.wiki/w/WAR#u47516b1", "type": "hierarchy", "primary": true, "order": 0}, {"from": "topic:2", "to": "https://mlbpark.donga.com/mp/b.php?b=kbotown&id=2026101500#u602ea36", "type": "hierarchy", "primary": true, "order": 1}, {"from": "topic:2", "to": "https://www.chosun.com/sports/baseball/2026/10/14/#u17b1782", "type": "hierarchy", "primary": true, "order": 0}, {"from": "https://blog.naver.com/ballpark/223777#u7e8c057", "to": "https://www.chosun.com/sports/baseball/2026/10/14/#u17b1782", "type": "related"}]}'::jsonb, '[{"unitKey": "https://blog.naver.com/ballpark/223777#u7e8c057", "pageId": "https://blog.naver.com/ballpark/223777", "pid": "u7e8c057", "order": 0, "pageTitle": "잠실 직관 좌석 추천", "pageUrl": "https://blog.naver.com/ballpark/223777", "text": "잠실은 1루가 홈팀 응원석인 날이 많다. 응원을 즐기려면 내야 응원석, 경기를 편하게 보려면 중앙 테이블석이 좋다.", "clusterLabel": "Reading", "score": 2.259, "dwellMs": 5237, "firstSeenAt": "2026-10-15T20:26:00+09:00", "lastSeenAt": "2026-10-15T20:26:05.237000+09:00", "mergedFrom": []}, {"unitKey": "https://sports.news.naver.com/kbaseball/news/read?oid=001&aid=0014#u5b30ec9", "pageId": "https://sports.news.naver.com/kbaseball/news/read?oid=001&aid=0014", "pid": "u5b30ec9", "order": 0, "pageTitle": "OPS 로 보는 타자", "pageUrl": "https://sports.news.naver.com/kbaseball/news/read?oid=001&aid=0014", "text": "OPS 는 출루율과 장타율을 더한 값으로, 0.900 을 넘으면 리그 정상급 타자로 본다. 타율보다 득점 기여를 더 잘 보여 준다.", "clusterLabel": "Deep Reading", "score": 3.175, "dwellMs": 9379, "firstSeenAt": "2026-10-15T20:28:00+09:00", "lastSeenAt": "2026-10-15T20:28:09.379000+09:00", "mergedFrom": []}, {"unitKey": "https://www.yna.co.kr/view/AKR20261012000100007#ue080cb0", "pageId": "https://www.yna.co.kr/view/AKR20261012000100007", "pid": "ue080cb0", "order": 0, "pageTitle": "올해 타격왕 경쟁", "pageUrl": "https://www.yna.co.kr/view/AKR20261012000100007", "text": "타격왕은 규정 타석(경기 수 × 3.1)을 채운 타자 중 타율이 가장 높은 선수에게 돌아간다. 막판 결장으로 규정 타석을 못 채우면 순위에서 빠진다.", "clusterLabel": "Reading", "score": 2.273, "dwellMs": 4427, "firstSeenAt": "2026-10-15T20:29:00+09:00", "lastSeenAt": "2026-10-15T20:29:04.427000+09:00", "mergedFrom": []}, {"unitKey": "https://namu.wiki/w/WAR#u47516b1", "pageId": "https://namu.wiki/w/WAR", "pid": "u47516b1", "order": 0, "pageTitle": "WAR 이란", "pageUrl": "https://namu.wiki/w/WAR", "text": "WAR 은 대체 선수보다 팀 승리를 몇 번 더 만들었는지 나타낸다. 포지션과 구장 차이를 보정해서 선수끼리 비교할 때 많이 쓴다.", "clusterLabel": "Deep Reading", "score": 3.616, "dwellMs": 14107, "firstSeenAt": "2026-10-15T20:30:00+09:00", "lastSeenAt": "2026-10-15T20:30:14.107000+09:00", "mergedFrom": []}, {"unitKey": "https://mlbpark.donga.com/mp/b.php?b=kbotown&id=2026101500#u602ea36", "pageId": "https://mlbpark.donga.com/mp/b.php?b=kbotown&id=2026101500", "pid": "u602ea36", "order": 0, "pageTitle": "선발 이닝 수 논쟁", "pageUrl": "https://mlbpark.donga.com/mp/b.php?b=kbotown&id=2026101500", "text": "선발 투수가 6이닝 이상을 꾸준히 던져 주면 불펜 소모가 줄어 시즌 후반 순위 싸움에서 큰 차이가 난다.", "clusterLabel": "Reading", "score": 2.729, "dwellMs": 6471, "firstSeenAt": "2026-10-15T20:31:00+09:00", "lastSeenAt": "2026-10-15T20:31:06.471000+09:00", "mergedFrom": []}, {"unitKey": "https://www.chosun.com/sports/baseball/2026/10/14/#u17b1782", "pageId": "https://www.chosun.com/sports/baseball/2026/10/14/", "pid": "u17b1782", "order": 0, "pageTitle": "피치클록 도입 효과", "pageUrl": "https://www.chosun.com/sports/baseball/2026/10/14/", "text": "피치 클록 도입 뒤 경기 시간이 평균 20분 가까이 줄었다. 투수는 주자가 없을 때 정해진 시간 안에 투구해야 한다.", "clusterLabel": "Deep Reading", "score": 3.939, "dwellMs": 14794, "firstSeenAt": "2026-10-15T20:32:00+09:00", "lastSeenAt": "2026-10-15T20:32:14.794000+09:00", "mergedFrom": []}]'::jsonb, '[{"unitKey": "https://blog.naver.com/ballpark/223777#u7e8c057", "pageId": "https://blog.naver.com/ballpark/223777", "pid": "u7e8c057", "order": 0, "clusterLabel": "Reading", "behaviorScore": 2.259, "finalScore": 2.259, "rank": 6, "dwellMs": 5237, "exposureMs": 10474, "firstSeenAt": "2026-10-15T20:26:00+09:00", "lastSeenAt": "2026-10-15T20:26:05.237000+09:00", "selected": true, "mergedInto": null}, {"unitKey": "https://cafe.naver.com/kbofan/301122#u101ebf3", "pageId": "https://cafe.naver.com/kbofan/301122", "pid": "u101ebf3", "order": 0, "clusterLabel": "Scanning", "behaviorScore": 1.176, "finalScore": 1.176, "rank": 7, "dwellMs": 894, "exposureMs": 1788, "firstSeenAt": "2026-10-15T20:27:00+09:00", "lastSeenAt": "2026-10-15T20:27:00.894000+09:00", "selected": false, "mergedInto": null}, {"unitKey": "https://sports.news.naver.com/kbaseball/news/read?oid=001&aid=0014#u5b30ec9", "pageId": "https://sports.news.naver.com/kbaseball/news/read?oid=001&aid=0014", "pid": "u5b30ec9", "order": 0, "clusterLabel": "Deep Reading", "behaviorScore": 3.175, "finalSco