https://cafe.naver.com/dogcafe/50213#u9af5c6b", "type": "hierarchy", "primary": true, "order": 0}, {"from": "https://blog.naver.com/doglog/310442#ue80686b", "to": "https://cafe.naver.com/dogcafe/50213#u9af5c6b", "type": "related"}]}'::jsonb, '[{"unitKey": "https://blog.naver.com/doglog/310442#ue80686b", "pageId": "https://blog.naver.com/doglog/310442", "pid": "ue80686b", "order": 0, "pageTitle": "강아지 산책 시간 정하기", "pageUrl": "https://blog.naver.com/doglog/310442", "text": "소형견은 하루 30분, 활동량이 많은 중대형견은 하루 1~2시간 산책이 권장된다. 산책 시간보다 냄새를 맡게 해 주는 시간이 더 중요하다.", "clusterLabel": "Reading", "score": 2.231, "dwellMs": 5983, "firstSeenAt": "2026-10-15T20:51:00+09:00", "lastSeenAt": "2026-10-15T20:51:05.983000+09:00", "mergedFrom": []}, {"unitKey": "https://blog.naver.com/doglog/310442#u308a26a", "pageId": "https://blog.naver.com/doglog/310442", "pid": "u308a26a", "order": 1, "pageTitle": "강아지 산책 시간 정하기", "pageUrl": "https://blog.naver.com/doglog/310442", "text": "노즈워크는 후각을 쓰게 해 짧은 시간에도 에너지를 많이 소모시킨다. 비 오는 날 실내에서 대신하기 좋은 놀이다.", "clusterLabel": "Deep Reading", "score": 3.838, "dwellMs": 11287, "firstSeenAt": "2026-10-15T20:52:00+09:00", "lastSeenAt": "2026-10-15T20:52:11.287000+09:00", "mergedFrom": []}, {"unitKey": "https://cafe.naver.com/dogcafe/50213#u9af5c6b", "pageId": "https://cafe.naver.com/dogcafe/50213", "pid": "u9af5c6b", "order": 0, "pageTitle": "분리불안 고민", "pageUrl": "https://cafe.naver.com/dogcafe/50213", "text": "분리불안이 있는 강아지는 외출 준비 행동에 무뎌지게 하는 연습이 효과적이다. 열쇠를 들었다 내려놓기를 반복해 신호의 의미를 줄인다.", "clusterLabel": "Deep Reading", "score": 3.83, "dwellMs": 10171, "firstSeenAt": "2026-10-15T20:55:00+09:00", "lastSeenAt": "2026-10-15T20:55:10.171000+09:00", "mergedFrom": []}]'::jsonb, '[{"unitKey": "https://blog.naver.com/doglog/310442#ue80686b", "pageId": "https://blog.naver.com/doglog/310442", "pid": "ue80686b", "order": 0, "clusterLabel": "Reading", "behaviorScore": 2.231, "finalScore": 2.231, "rank": 3, "dwellMs": 5983, "exposureMs": 11966, "firstSeenAt": "2026-10-15T20:51:00+09:00