ession_id": "seed-20", "user_id": "seed-user-1", "page_id": "https://snowtrip.tistory.com/12", "pid": "u725db5d", "char_len": 66, "dwell_ms": 6795, "dwell_per_char": 102.955, "fixed_ratio": 0.481, "revisit_count": 1, "scroll_speed_mean": 664.3, "cursor_speed_mean": null, "cursor_speed_z": null, "has_highlight": 0, "has_copy": 0, "cluster_label": "Reading", "behavior_score": 2.495}, {"session_id": "seed-20", "user_id": "seed-user-1", "page_id": "https://www.youtube.com/watch?v=skibasic02", "pid": "u8e6352d", "char_len": 63, "dwell_ms": 7819, "dwell_per_char": 124.111, "fixed_ratio": 0.411, "revisit_count": 1, "scroll_speed_mean": 299.2, "cursor_speed_mean": null, "cursor_speed_z": null, "has_highlight": 0, "has_copy": 0, "cluster_label": "Reading", "behavior_score": 2.374}]'::jsonb, 'global', 'A', TIMESTAMP '2026-10-10 22:19:00', TIMESTAMP '2026-10-10 22:19:00');
INSERT INTO session_raw_payloads (session_id, user_id, payload, received_at, expires_at) VALUES (1, 1, '{"kind": "rbc-session", "bundleVersion": 1, "session": {"sessionId": "seed-1", "tester": {"testId": "seed-user-1"}, "startedAt": "2026-10-17T17:03:00+09:00", "endedAt": "2026-10-17T17:42:00+09:00", "stopReason": "user", "focusMs": 1170000, "searchQuery": null, "tickMs": 150}, "pages": [{"meta": {"pageId": "https://blog.naver.com/catlover/223001", "url": "https://blog.naver.com/catlover/223001", "title": "고양이 물 잘 먹이는 법", "paragraphs": [{"pid": "u1639fc1", "order": 0, "text": "고양이 음수량은 체중 1kg 당 하루 약 40~50ml 가 권장된다. 건사료만 먹는 고양이는 물이 부족해지기 쉬워서 습식 사료를 섞어 주는 게 좋다.", "charLen": 83}, {"pid": "u40d0c59", "order": 1, "text": "흐르는 물을 좋아하는 고양이가 많아 자동 급수기(정수기)를 두면 음수량이 눈에 띄게 늘어난다. 필터는 2~4주마다 갈아 주는 것이 위생적이다.", "charLen": 79}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-1-0", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-1-0", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-1-0", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://namu.wiki/w/고양이/건강", "url": "https://namu.wiki/w/고양이/건강", "title": "고양이 건강 관리", "paragraphs": [{"pid": "ub77e414", "order": 0, "text": "물을 적게 마시는 습관이 오래 가면 신장 질환과 방광염 위험이 높아진다. 노령묘는 6개월마다 혈액 검사로 신장 수치를 확인하는 편이 안전하다.", "charLen": 79}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-1-1", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-1-1", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-1-1", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://cafe.naver.com/ilovecat/88120", "url": "https://cafe.naver.com/ilovecat/88120", "title": "모래 추천 받아요", "paragraphs": [{"pid": "u6ba03d9", "order": 0, "text": "벤토나이트 모래는 응고력이 좋아 치우기 쉽지만 먼지가 날 수 있다. 두부 모래는 먼지가 적고 변기에 버릴 수 있다는 장점이 있다.", "charLen": 72}, {"pid": "uc87bba4", "order": 1, "text": "화장실 개수는 고양이 수보다 하나 더 많게 두는 것이 기본이다. 여러 마리를 키우면 서로 다른 방에 나눠 두어야 스트레스가 줄어든다.", "charLen": 74}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-1-2", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-1-2", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-1-2", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://brunch.co.kr/@meowdiary/41", "url": "https://brunch.co.kr/@meowdiary/41", "title": "실내묘 놀이 루틴", "paragraphs": [{"pid": "u40618d0", "order": 0, "text": "낚싯대 장난감으로 하루 두 번, 10~15분씩 사냥 놀이를 해 주면 실내묘의 운동 부족과 야간 우다다가 줄어든다.", "charLen": 63}, {"pid": "u2e7f0d0", "order": 1, "text": "고양이는 높은 곳에서 주변을 내려다볼 때 안정감을 느낀다. 캣타워나 벽 선반으로 수직 공간을 만들어 주면 영역 다툼도 줄어든다.", "charLen": 71}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-1-3", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-1-3", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-1-3", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}]}'::jsonb, TIMESTAMP '2026-10-17 17:42:00', TIMESTAMP '2026-10-17 17:43:00' + interval '21 days');
INSERT INTO session_raw_payloads (session_id, user_id, payload, received_at, expires_at) VALUES (2, 1, '{"kind": "rbc-session", "bundleVersion": 1, "session": {"sessionId": "seed-2", "tester": {"testId": "seed-user-1"}, "startedAt": "2026-10-28T05:10:00+09:00", "endedAt": "2026-10-28T05:53:00+09:00", "stopReason": "user", "focusMs": 1290000, "searchQuery": null, "tickMs": 150}, "pages": [{"meta": {"pageId": "https://blog.naver.com/doglog/310442", "url": "https://blog.naver.com/doglog/310442", "title": "강아지 산책 시간 정하기", "paragraphs": [{"pid": "ue80686b", "order": 0, "text": "소형견은 하루 30분, 활동량이 많은 중대형견은 하루 1~2시간 산책이 권장된다. 산책 시간보다 냄새를 맡게 해 주는 시간이 더 중요하다.", "charLen": 77}, {"pid": "u308a26a", "order": 1, "text": "노즈워크는 후각을 쓰게 해 짧은 시간에도 에너지를 많이 소모시킨다. 비 오는 날 실내에서 대신하기 좋은 놀이다.", "charLen": 62}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-2-0", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-2-0", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-2-0", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://dogpages.tistory.com/57", "url": "https://dogpages.tistory.com/57", "title": "여름·겨울 산책 주의", "paragraphs": [{"pid": "ufa017a6", "order": 0, "text": "한여름 아스팔트는 50도를 넘을 수 있어 발바닥 화상 위험이 크다. 손등을 바닥에 5초 대 보고 뜨거우면 산책 시간을 옮긴다.", "charLen": 70}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-2-1", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-2-1", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-2-1", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://www.youtube.com/watch?v=dogtrain01", "url": "https://www.youtube.com/watch?v=dogtrain01", "title": "기다려 훈련 3단계", "paragraphs": [{"pid": "ud4efdd2", "order": 0, "text": "기다려 훈련은 1초부터 시작해 성공할 때마다 시간을 늘린다. 보상은 행동 직후 2초 안에 줘야 강아지가 무엇을 칭찬받는지 이해한다.", "charLen": 73}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-2-2", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-2-2", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-2-2", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://cafe.naver.com/dogcafe/50213", "url": "https://cafe.naver.com/dogcafe/50213", "title": "분리불안 고민", "paragraphs": [{"pid": "u9af5c6b", "order": 0, "text": "분리불안이 있는 강아지는 외출 준비 행동에 무뎌지게 하는 연습이 효과적이다. 열쇠를 들었다 내려놓기를 반복해 신호의 의미를 줄인다.", "charLen": 73}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-2-3", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-2-3", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-2-3", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://dogpages.tistory.com/62", "url": "https://dogpages.tistory.com/62", "title": "사료 바꾸는 법", "paragraphs": [{"pid": "ucdc1895", "order": 0, "text": "사료를 바꿀 때는 7~10일에 걸쳐 새 사료 비율을 25%씩 늘려야 설사 같은 장 트러블을 피할 수 있다.", "charLen": 59}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-2-4", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-2-4", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-2-4", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://namu.wiki/w/개/먹이", "url": "https://namu.wiki/w/개/먹이", "title": "강아지가 먹으면 안 되는 음식", "paragraphs": [{"pid": "u61fa822", "order": 0, "text": "포도와 건포도, 초콜릿, 양파, 자일리톨은 소량으로도 강아지에게 위험하다. 먹었다면 바로 동물병원에 연락한다.", "charLen": 61}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-2-5", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-2-5", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-2-5", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}]}'::jsonb, TIMESTAMP '2026-10-28 05:53:00', TIMESTAMP '2026-10-28 05:54:00' + interval '21 days');
INSERT INTO session_raw_payloads (session_id, user_id, payload, received_at, expires_at) VALUES (3, 2, '{"kind": "rbc-session", "bundleVersion": 1, "session": {"sessionId": "seed-3", "tester": {"testId": "seed-user-2"}, "startedAt": "2026-10-23T12:26:00+09:00", "endedAt": "2026-10-23T13:13:00+09:00", "stopReason": "user", "focusMs": 1410000, "searchQuery": null, "tickMs": 150}, "pages": [{"meta": {"pageId": "https://docs.spring.io/spring-data/jpa/reference/jpa/query-methods.html", "url": "https://docs.spring.io/spring-data/jpa/reference/jpa/query-methods.html", "title": "Spring Data JPA 쿼리 메서드", "paragraphs": [{"pid": "uf6cfd4a", "order": 0, "text": "Spring Data JPA 는 메서드 이름으로 쿼리를 만든다. findByUserIdAndDeletedAtIsNull 처럼 조건을 이어 쓰면 where 절이 자동으로 생성된다.", "charLen": 99}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-3-0", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-3-0", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-3-0", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://velog.io/@devhan/jpa-n-plus-1", "url": "https://velog.io/@devhan/jpa-n-plus-1", "title": "JPA N+1 문제 정리", "paragraphs": [{"pid": "udabe65c", "order": 0, "text": "연관 엔티티를 지연 로딩하면 목록을 조회할 때 쿼리가 N+1 번 나갈 수 있다. 페치 조인이나 EntityGraph 로 한 번에 가져오면 해결된다.", "charLen": 82}, {"pid": "u6d0801a", "order": 1, "text": "hibernate.default_batch_fetch_size 를 설정하면 지연 로딩 쿼리를 IN 절로 묶어 보내서 N+1 을 크게 줄일 수 있다.", "charLen": 82}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-3-1", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-3-1", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-3-1", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://techblog.woowahan.com/2711", "url": "https://techblog.woowahan.com/2711", "title": "JWT 토큰 갱신 전략", "paragraphs": [{"pid": "uf3cd4f4", "order": 0, "text": "리프레시 토큰은 재사용을 막기 위해 사용할 때마다 새로 발급하는 회전 방식이 안전하다. 탈취된 토큰이 재사용되면 해당 계열 전체를 폐기한다.", "charLen": 78}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-3-2", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-3-2", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-3-2", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://stackoverflow.com/questions/27726066", "url": "https://stackoverflow.com/questions/27726066", "title": "JWT vs session", "paragraphs": [{"pid": "u91988db", "order": 0, "text": "JWT 는 서버가 상태를 저장하지 않아 확장에 유리하지만, 즉시 로그아웃 처리가 어렵다. 그래서 만료 시간을 짧게 두고 리프레시 토큰을 함께 쓴다.", "charLen": 82}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-3-3", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-3-3", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-3-3", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://docs.spring.io/spring-boot/reference/testing/index.html", "url": "https://docs.spring.io/spring-boot/reference/testing/index.html", "title": "Spring Boot 테스트", "paragraphs": [{"pid": "u48dbe29", "order": 0, "text": "SpringBootTest 는 전체 컨텍스트를 띄워 느리지만 실제와 가깝다. 컨트롤러만 확인할 때는 MockMvc 로 HTTP 요청과 응답을 검증한다.", "charLen": 84}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-3-4", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-3-4", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-3-4", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://velog.io/@devhan/testcontainers", "url": "https://velog.io/@devhan/testcontainers", "title": "Testcontainers 로 DB 테스트", "paragraphs": [{"pid": "u9ef74cd", "order": 0, "text": "H2 와 운영 DB 의 문법 차이 때문에 테스트는 통과하고 운영에서 깨지는 일이 있다. Testcontainers 로 실제 PostgreSQL 을 띄우면 이런 차이를 줄일 수 있다.", "charLen": 101}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-3-5", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-3-5", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-3-5", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}]}'::jsonb, TIMESTAMP '2026-10-23 13:13:00', TIMESTAMP '2026-10-23 13:14:00' + interval '21 days');
INSERT INTO session_raw_payloads (session_id, user_id, payload, received_at, expires_at) VALUES (4, 3, '{"kind": "rbc-session", "bundleVersion": 1, "session": {"sessionId": "seed-4", "tester": {"testId": "seed-user-3"}, "startedAt": "2026-10-22T14:38:00+09:00", "endedAt": "2026-10-22T15:47:00+09:00", "stopReason": "user", "focusMs": 2070000, "searchQuery": null, "tickMs": 150}, "pages": [{"meta": {"pageId": "https://sports.news.naver.com/kbaseball/news/read?oid=001&aid=0014", "url": "https://sports.news.naver.com/kbaseball/news/read?oid=001&aid=0014", "title": "OPS 로 보는 타자", "paragraphs": [{"pid": "u5b30ec9", "order": 0, "text": "OPS 는 출루율과 장타율을 더한 값으로, 0.900 을 넘으면 리그 정상급 타자로 본다. 타율보다 득점 기여를 더 잘 보여 준다.", "charLen": 73}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-4-0", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-4-0", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-4-0", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://www.yna.co.kr/view/AKR20261012000100007", "url": "https://www.yna.co.kr/view/AKR20261012000100007", "title": "올해 타격왕 경쟁", "paragraphs": [{"pid": "ue080cb0", "order": 0, "text": "타격왕은 규정 타석(경기 수 × 3.1)을 채운 타자 중 타율이 가장 높은 선수에게 돌아간다. 막판 결장으로 규정 타석을 못 채우면 순위에서 빠진다.", "charLen": 83}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-4-1", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-4-1", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-4-1", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://namu.wiki/w/WAR", "url": "https://namu.wiki/w/WAR", "title": "WAR 이란", "paragraphs": [{"pid": "u47516b1", "order": 0, "text": "WAR 은 대체 선수보다 팀 승리를 몇 번 더 만들었는지 나타낸다. 포지션과 구장 차이를 보정해서 선수끼리 비교할 때 많이 쓴다.", "charLen": 72}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-4-2", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-4-2", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-4-2", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://mlbpark.donga.com/mp/b.php?b=kbotown&id=2026101500", "url": "https://mlbpark.donga.com/mp/b.php?b=kbotown&id=2026101500", "title": "선발 이닝 수 논쟁", "paragraphs": [{"pid": "u602ea36", "order": 0, "text": "선발 투수가 6이닝 이상을 꾸준히 던져 주면 불펜 소모가 줄어 시즌 후반 순위 싸움에서 큰 차이가 난다.", "charLen": 58}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-4-3", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-4-3", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-4-3", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://www.chosun.com/sports/baseball/2026/10/14/", "url": "https://www.chosun.com/sports/baseball/2026/10/14/", "title": "피치클록 도입 효과", "paragraphs": [{"pid": "u17b1782", "order": 0, "text": "피치 클록 도입 뒤 경기 시간이 평균 20분 가까이 줄었다. 투수는 주자가 없을 때 정해진 시간 안에 투구해야 한다.", "charLen": 65}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-4-4", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-4-4", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-4-4", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://blog.naver.com/ballpark/223777", "url": "https://blog.naver.com/ballpark/223777", "title": "잠실 직관 좌석 추천", "paragraphs": [{"pid": "u7e8c057", "order": 0, "text": "잠실은 1루가 홈팀 응원석인 날이 많다. 응원을 즐기려면 내야 응원석, 경기를 편하게 보려면 중앙 테이블석이 좋다.", "charLen": 64}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-4-5", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-4-5", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-4-5", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://cafe.naver.com/kbofan/301122", "url": "https://cafe.naver.com/kbofan/301122", "title": "야구장 먹거리", "paragraphs": [{"pid": "u101ebf3", "order": 0, "text": "야구장 먹거리는 경기 시작 전에 사 두는 게 좋다. 5회 이후엔 줄이 길어져 이닝을 놓치기 쉽다.", "charLen": 54}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-4-6", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-4-6", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-4-6", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}]}'::jsonb, TIMESTAMP '2026-10-22 15:47:00', TIMESTAMP '2026-10-22 15:48:00' + interval '21 days');
INSERT INTO session_raw_payloads (session_id, user_id, payload, received_at, expires_at) VALUES (5, 1, '{"kind": "rbc-session", "bundleVersion": 1, "session": {"sessionId": "seed-5", "tester": {"testId": "seed-user-1"}, "startedAt": "2026-10-19T21:36:00+09:00", "endedAt": "2026-10-19T22:22:00+09:00", "stopReason": "user", "focusMs": 1380000, "searchQuery": null, "tickMs": 150}, "pages": [{"meta": {"pageId": "https://www.hankyung.com/article/2026101820001", "url": "https://www.hankyung.com/article/2026101820001", "title": "난방비 아끼는 법", "paragraphs": [{"pid": "uc020c59", "order": 0, "text": "보일러를 완전히 끄기보다 외출 모드로 두는 편이 난방비가 덜 든다. 다시 데우는 데 드는 에너지가 더 크기 때문이다.", "charLen": 65}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-5-0", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-5-0", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-5-0", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://blog.naver.com/homecare/224010", "url": "https://blog.naver.com/homecare/224010", "title": "뽁뽁이와 문풍지", "paragraphs": [{"pid": "u868c7b1", "order": 0, "text": "창문에 단열 에어캡을 붙이고 문틈에 문풍지를 대면 실내 온도를 2~3도 지킬 수 있다. 결로가 생기면 자주 환기한다.", "charLen": 65}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-5-1", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-5-1", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-5-1", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://snowtrip.tistory.com/12", "url": "https://snowtrip.tistory.com/12", "title": "스키장 처음 갈 때", "paragraphs": [{"pid": "u874925f", "order": 0, "text": "스키를 처음 탄다면 첫날은 강습을 받고 초보 코스에서 멈추는 법부터 익히는 것이 안전하다. 리프트 시즌권보다 일일권이 낫다.", "charLen": 69}, {"pid": "u725db5d", "order": 1, "text": "스키장 옷은 땀을 빼는 속옷, 보온 중간층, 방수 겉옷으로 겹쳐 입어야 한다. 면 소재는 땀이 식으며 체온을 빼앗는다.", "charLen": 66}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-5-2", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-5-2", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-5-2", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://www.youtube.com/watch?v=skibasic02", "url": "https://www.youtube.com/watch?v=skibasic02", "title": "스키 A자 자세", "paragraphs": [{"pid": "u8e6352d", "order": 0, "text": "A자 자세는 스키 앞쪽을 모으고 뒤를 벌려 속도를 줄이는 기본 제동 자세다. 무릎을 살짝 굽혀야 넘어지지 않는다.", "charLen": 63}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-5-3", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-5-3", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-5-3", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://health.chosun.com/site/data/html_dir/2026/10/20/", "url": "https://health.chosun.com/site/data/html_dir/2026/10/20/", "title": "겨울철 건조증", "paragraphs": [{"pid": "u3e3e4ac", "order": 0, "text": "겨울철 실내 습도는 40~60% 가 적당하다. 가습기를 쓸 때는 매일 물을 갈고 주 1회 이상 세척해야 세균 번식을 막는다.", "charLen": 69}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-5-4", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-5-4", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-5-4", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://www.yna.co.kr/view/AKR20261021000300017", "url": "https://www.yna.co.kr/view/AKR20261021000300017", "title": "독감 예방접종 시작", "paragraphs": [{"pid": "u33b8503", "order": 0, "text": "독감 예방접종은 항체가 생기기까지 2주 정도 걸려 10~11월에 맞는 것이 좋다. 65세 이상과 어린이는 무료로 맞을 수 있다.", "charLen": 71}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-5-5", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-5-5", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-5-5", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}]}'::jsonb, TIMESTAMP '2026-10-19 22:22:00', TIMESTAMP '2026-10-19 22:23:00' + interval '21 days');
INSERT INTO session_raw_payloads (session_id, user_id, payload, received_at, expires_at) VALUES (6, 4, '{"kind": "rbc-session", "bundleVersion": 1, "session": {"sessionId": "seed-6", "tester": {"testId": "seed-user-4"}, "startedAt": "2026-10-21T21:12:00+09:00", "endedAt": "2026-10-21T22:13:00+09:00", "stopReason": "user", "focusMs": 1830000, "searchQuery": null, "tickMs": 150}, "pages": [{"meta": {"pageId": "https://cafe.naver.com/ilovecat/88120", "url": "https://cafe.naver.com/ilovecat/88120", "title": "모래 추천 받아요", "paragraphs": [{"pid": "u6ba03d9", "order": 0, "text": "벤토나이트 모래는 응고력이 좋아 치우기 쉽지만 먼지가 날 수 있다. 두부 모래는 먼지가 적고 변기에 버릴 수 있다는 장점이 있다.", "charLen": 72}, {"pid": "uc87bba4", "order": 1, "text": "화장실 개수는 고양이 수보다 하나 더 많게 두는 것이 기본이다. 여러 마리를 키우면 서로 다른 방에 나눠 두어야 스트레스가 줄어든다.", "charLen": 74}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-6-0", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-6-0", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-6-0", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://brunch.co.kr/@meowdiary/41", "url": "https://brunch.co.kr/@meowdiary/41", "title": "실내묘 놀이 루틴", "paragraphs": [{"pid": "u40618d0", "order": 0, "text": "낚싯대 장난감으로 하루 두 번, 10~15분씩 사냥 놀이를 해 주면 실내묘의 운동 부족과 야간 우다다가 줄어든다.", "charLen": 63}, {"pid": "u2e7f0d0", "order": 1, "text": "고양이는 높은 곳에서 주변을 내려다볼 때 안정감을 느낀다. 캣타워나 벽 선반으로 수직 공간을 만들어 주면 영역 다툼도 줄어든다.", "charLen": 71}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-6-1", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-6-1", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-6-1", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}]}'::jsonb, TIMESTAMP '2026-10-21 22:13:00', TIMESTAMP '2026-10-21 22:14:00' + interval '21 days');
INSERT INTO session_raw_payloads (session_id, user_id, payload, received_at, expires_at) VALUES (7, 5, '{"kind": "rbc-session", "bundleVersion": 1, "session": {"sessionId": "seed-7", "tester": {"testId": "seed-user-5"}, "startedAt": "2026-10-19T00:18:00+09:00", "endedAt": "2026-10-19T01:30:00+09:00", "stopReason": "user", "focusMs": 2160000, "searchQuery": null, "tickMs": 150}, "pages": [{"meta": {"pageId": "https://www.youtube.com/watch?v=dogtrain01", "url": "https://www.youtube.com/watch?v=dogtrain01", "title": "기다려 훈련 3단계", "paragraphs": [{"pid": "ud4efdd2", "order": 0, "text": "기다려 훈련은 1초부터 시작해 성공할 때마다 시간을 늘린다. 보상은 행동 직후 2초 안에 줘야 강아지가 무엇을 칭찬받는지 이해한다.", "charLen": 73}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-7-0", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-7-0", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-7-0", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://cafe.naver.com/dogcafe/50213", "url": "https://cafe.naver.com/dogcafe/50213", "title": "분리불안 고민", "paragraphs": [{"pid": "u9af5c6b", "order": 0, "text": "분리불안이 있는 강아지는 외출 준비 행동에 무뎌지게 하는 연습이 효과적이다. 열쇠를 들었다 내려놓기를 반복해 신호의 의미를 줄인다.", "charLen": 73}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-7-1", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-7-1", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-7-1", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://dogpages.tistory.com/62", "url": "https://dogpages.tistory.com/62", "title": "사료 바꾸는 법", "paragraphs": [{"pid": "ucdc1895", "order": 0, "text": "사료를 바꿀 때는 7~10일에 걸쳐 새 사료 비율을 25%씩 늘려야 설사 같은 장 트러블을 피할 수 있다.", "charLen": 59}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-7-2", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-7-2", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-7-2", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://namu.wiki/w/개/먹이", "url": "https://namu.wiki/w/개/먹이", "title": "강아지가 먹으면 안 되는 음식", "paragraphs": [{"pid": "u61fa822", "order": 0, "text": "포도와 건포도, 초콜릿, 양파, 자일리톨은 소량으로도 강아지에게 위험하다. 먹었다면 바로 동물병원에 연락한다.", "charLen": 61}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-7-3", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-7-3", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-7-3", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}]}'::jsonb, TIMESTAMP '2026-10-19 01:30:00', TIMESTAMP '2026-10-19 01:31:00' + interval '21 days');
INSERT INTO session_raw_payloads (session_id, user_id, payload, received_at, expires_at) VALUES (8, 1, '{"kind": "rbc-session", "bundleVersion": 1, "session": {"sessionId": "seed-8", "tester": {"testId": "seed-user-1"}, "startedAt": "2026-10-20T03:40:00+09:00", "endedAt": "2026-10-20T04:56:00+09:00", "stopReason": "user", "focusMs": 2280000, "searchQuery": null, "tickMs": 150}, "pages": [{"meta": {"pageId": "https://techblog.woowahan.com/2711", "url": "https://techblog.woowahan.com/2711", "title": "JWT 토큰 갱신 전략", "paragraphs": [{"pid": "uf3cd4f4", "order": 0, "text": "리프레시 토큰은 재사용을 막기 위해 사용할 때마다 새로 발급하는 회전 방식이 안전하다. 탈취된 토큰이 재사용되면 해당 계열 전체를 폐기한다.", "charLen": 78}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-8-0", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-8-0", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-8-0", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://stackoverflow.com/questions/27726066", "url": "https://stackoverflow.com/questions/27726066", "title": "JWT vs session", "paragraphs": [{"pid": "u91988db", "order": 0, "text": "JWT 는 서버가 상태를 저장하지 않아 확장에 유리하지만, 즉시 로그아웃 처리가 어렵다. 그래서 만료 시간을 짧게 두고 리프레시 토큰을 함께 쓴다.", "charLen": 82}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-8-1", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-8-1", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-8-1", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://docs.spring.io/spring-boot/reference/testing/index.html", "url": "https://docs.spring.io/spring-boot/reference/testing/index.html", "title": "Spring Boot 테스트", "paragraphs": [{"pid": "u48dbe29", "order": 0, "text": "SpringBootTest 는 전체 컨텍스트를 띄워 느리지만 실제와 가깝다. 컨트롤러만 확인할 때는 MockMvc 로 HTTP 요청과 응답을 검증한다.", "charLen": 84}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-8-2", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-8-2", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-8-2", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://velog.io/@devhan/testcontainers", "url": "https://velog.io/@devhan/testcontainers", "title": "Testcontainers 로 DB 테스트", "paragraphs": [{"pid": "u9ef74cd", "order": 0, "text": "H2 와 운영 DB 의 문법 차이 때문에 테스트는 통과하고 운영에서 깨지는 일이 있다. Testcontainers 로 실제 PostgreSQL 을 띄우면 이런 차이를 줄일 수 있다.", "charLen": 101}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-8-3", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-8-3", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-8-3", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}]}'::jsonb, TIMESTAMP '2026-10-20 04:56:00', TIMESTAMP '2026-10-20 04:57:00' + interval '21 days');
INSERT INTO session_raw_payloads (session_id, user_id, payload, received_at, expires_at) VALUES (9, 6, '{"kind": "rbc-session", "bundleVersion": 1, "session": {"sessionId": "seed-9", "tester": {"testId": "seed-user-6"}, "startedAt": "2026-10-29T02:44:00+09:00", "endedAt": "2026-10-29T03:20:00+09:00", "stopReason": "user", "focusMs": 1080000, "searchQuery": null, "tickMs": 150}, "pages": [{"meta": {"pageId": "https://mlbpark.donga.com/mp/b.php?b=kbotown&id=2026101500", "url": "https://mlbpark.donga.com/mp/b.php?b=kbotown&id=2026101500", "title": "선발 이닝 수 논쟁", "paragraphs": [{"pid": "u602ea36", "order": 0, "text": "선발 투수가 6이닝 이상을 꾸준히 던져 주면 불펜 소모가 줄어 시즌 후반 순위 싸움에서 큰 차이가 난다.", "charLen": 58}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-9-0", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-9-0", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-9-0", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://www.chosun.com/sports/baseball/2026/10/14/", "url": "https://www.chosun.com/sports/baseball/2026/10/14/", "title": "피치클록 도입 효과", "paragraphs": [{"pid": "u17b1782", "order": 0, "text": "피치 클록 도입 뒤 경기 시간이 평균 20분 가까이 줄었다. 투수는 주자가 없을 때 정해진 시간 안에 투구해야 한다.", "charLen": 65}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-9-1", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-9-1", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-9-1", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://blog.naver.com/ballpark/223777", "url": "https://blog.naver.com/ballpark/223777", "title": "잠실 직관 좌석 추천", "paragraphs": [{"pid": "u7e8c057", "order": 0, "text": "잠실은 1루가 홈팀 응원석인 날이 많다. 응원을 즐기려면 내야 응원석, 경기를 편하게 보려면 중앙 테이블석이 좋다.", "charLen": 64}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-9-2", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-9-2", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-9-2", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://cafe.naver.com/kbofan/301122", "url": "https://cafe.naver.com/kbofan/301122", "title": "야구장 먹거리", "paragraphs": [{"pid": "u101ebf3", "order": 0, "text": "야구장 먹거리는 경기 시작 전에 사 두는 게 좋다. 5회 이후엔 줄이 길어져 이닝을 놓치기 쉽다.", "charLen": 54}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-9-3", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-9-3", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-9-3", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}]}'::jsonb, TIMESTAMP '2026-10-29 03:20:00', TIMESTAMP '2026-10-29 03:21:00' + interval '21 days');
INSERT INTO session_raw_payloads (session_id, user_id, payload, received_at, expires_at) VALUES (10, 7, '{"kind": "rbc-session", "bundleVersion": 1, "session": {"sessionId": "seed-10", "tester": {"testId": "seed-user-7"}, "startedAt": "2026-10-28T16:35:00+09:00", "endedAt": "2026-10-28T17:47:00+09:00", "stopReason": "user", "focusMs": 2160000, "searchQuery": null, "tickMs": 150}, "pages": [{"meta": {"pageId": "https://snowtrip.tistory.com/12", "url": "https://snowtrip.tistory.com/12", "title": "스키장 처음 갈 때", "paragraphs": [{"pid": "u874925f", "order": 0, "text": "스키를 처음 탄다면 첫날은 강습을 받고 초보 코스에서 멈추는 법부터 익히는 것이 안전하다. 리프트 시즌권보다 일일권이 낫다.", "charLen": 69}, {"pid": "u725db5d", "order": 1, "text": "스키장 옷은 땀을 빼는 속옷, 보온 중간층, 방수 겉옷으로 겹쳐 입어야 한다. 면 소재는 땀이 식으며 체온을 빼앗는다.", "charLen": 66}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-10-0", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-10-0", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-10-0", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://www.youtube.com/watch?v=skibasic02", "url": "https://www.youtube.com/watch?v=skibasic02", "title": "스키 A자 자세", "paragraphs": [{"pid": "u8e6352d", "order": 0, "text": "A자 자세는 스키 앞쪽을 모으고 뒤를 벌려 속도를 줄이는 기본 제동 자세다. 무릎을 살짝 굽혀야 넘어지지 않는다.", "charLen": 63}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-10-1", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-10-1", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-10-1", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://health.chosun.com/site/data/html_dir/2026/10/20/", "url": "https://health.chosun.com/site/data/html_dir/2026/10/20/", "title": "겨울철 건조증", "paragraphs": [{"pid": "u3e3e4ac", "order": 0, "text": "겨울철 실내 습도는 40~60% 가 적당하다. 가습기를 쓸 때는 매일 물을 갈고 주 1회 이상 세척해야 세균 번식을 막는다.", "charLen": 69}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-10-2", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-10-2", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-10-2", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://www.yna.co.kr/view/AKR20261021000300017", "url": "https://www.yna.co.kr/view/AKR20261021000300017", "title": "독감 예방접종 시작", "paragraphs": [{"pid": "u33b8503", "order": 0, "text": "독감 예방접종은 항체가 생기기까지 2주 정도 걸려 10~11월에 맞는 것이 좋다. 65세 이상과 어린이는 무료로 맞을 수 있다.", "charLen": 71}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-10-3", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-10-3", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-10-3", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}]}'::jsonb, TIMESTAMP '2026-10-28 17:47:00', TIMESTAMP '2026-10-28 17:48:00' + interval '21 days');
INSERT INTO session_raw_payloads (session_id, user_id, payload, received_at, expires_at) VALUES (11, 1, '{"kind": "rbc-session", "bundleVersion": 1, "session": {"sessionId": "seed-11", "tester": {"testId": "seed-user-1"}, "startedAt": "2026-10-17T04:31:00+09:00", "endedAt": "2026-10-17T05:23:00+09:00", "stopReason": "user", "focusMs": 1560000, "searchQuery": null, "tickMs": 150}, "pages": [{"meta": {"pageId": "https://brunch.co.kr/@meowdiary/41", "url": "https://brunch.co.kr/@meowdiary/41", "title": "실내묘 놀이 루틴", "paragraphs": [{"pid": "u40618d0", "order": 0, "text": "낚싯대 장난감으로 하루 두 번, 10~15분씩 사냥 놀이를 해 주면 실내묘의 운동 부족과 야간 우다다가 줄어든다.", "charLen": 63}, {"pid": "u2e7f0d0", "order": 1, "text": "고양이는 높은 곳에서 주변을 내려다볼 때 안정감을 느낀다. 캣타워나 벽 선반으로 수직 공간을 만들어 주면 영역 다툼도 줄어든다.", "charLen": 71}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-11-0", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-11-0", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-11-0", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://blog.naver.com/catlover/223001", "url": "https://blog.naver.com/catlover/223001", "title": "고양이 물 잘 먹이는 법", "paragraphs": [{"pid": "u1639fc1", "order": 0, "text": "고양이 음수량은 체중 1kg 당 하루 약 40~50ml 가 권장된다. 건사료만 먹는 고양이는 물이 부족해지기 쉬워서 습식 사료를 섞어 주는 게 좋다.", "charLen": 83}, {"pid": "u40d0c59", "order": 1, "text": "흐르는 물을 좋아하는 고양이가 많아 자동 급수기(정수기)를 두면 음수량이 눈에 띄게 늘어난다. 필터는 2~4주마다 갈아 주는 것이 위생적이다.", "charLen": 79}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-11-1", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-11-1", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-11-1", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://namu.wiki/w/고양이/건강", "url": "https://namu.wiki/w/고양이/건강", "title": "고양이 건강 관리", "paragraphs": [{"pid": "ub77e414", "order": 0, "text": "물을 적게 마시는 습관이 오래 가면 신장 질환과 방광염 위험이 높아진다. 노령묘는 6개월마다 혈액 검사로 신장 수치를 확인하는 편이 안전하다.", "charLen": 79}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-11-2", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-11-2", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-11-2", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://cafe.naver.com/ilovecat/88120", "url": "https://cafe.naver.com/ilovecat/88120", "title": "모래 추천 받아요", "paragraphs": [{"pid": "u6ba03d9", "order": 0, "text": "벤토나이트 모래는 응고력이 좋아 치우기 쉽지만 먼지가 날 수 있다. 두부 모래는 먼지가 적고 변기에 버릴 수 있다는 장점이 있다.", "charLen": 72}, {"pid": "uc87bba4", "order": 1, "text": "화장실 개수는 고양이 수보다 하나 더 많게 두는 것이 기본이다. 여러 마리를 키우면 서로 다른 방에 나눠 두어야 스트레스가 줄어든다.", "charLen": 74}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-11-3", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-11-3", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-11-3", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}]}'::jsonb, TIMESTAMP '2026-10-17 05:23:00', TIMESTAMP '2026-10-17 05:24:00' + interval '21 days');
INSERT INTO session_raw_payloads (session_id, user_id, payload, received_at, expires_at) VALUES (12, 8, '{"kind": "rbc-session", "bundleVersion": 1, "session": {"sessionId": "seed-12", "tester": {"testId": "seed-user-8"}, "startedAt": "2026-10-11T04:17:00+09:00", "endedAt": "2026-10-11T04:58:00+09:00", "stopReason": "user", "focusMs": 1230000, "searchQuery": null, "tickMs": 150}, "pages": [{"meta": {"pageId": "https://dogpages.tistory.com/62", "url": "https://dogpages.tistory.com/62", "title": "사료 바꾸는 법", "paragraphs": [{"pid": "ucdc1895", "order": 0, "text": "사료를 바꿀 때는 7~10일에 걸쳐 새 사료 비율을 25%씩 늘려야 설사 같은 장 트러블을 피할 수 있다.", "charLen": 59}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-12-0", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-12-0", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-12-0", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://namu.wiki/w/개/먹이", "url": "https://namu.wiki/w/개/먹이", "title": "강아지가 먹으면 안 되는 음식", "paragraphs": [{"pid": "u61fa822", "order": 0, "text": "포도와 건포도, 초콜릿, 양파, 자일리톨은 소량으로도 강아지에게 위험하다. 먹었다면 바로 동물병원에 연락한다.", "charLen": 61}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-12-1", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-12-1", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-12-1", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://blog.naver.com/doglog/310442", "url": "https://blog.naver.com/doglog/310442", "title": "강아지 산책 시간 정하기", "paragraphs": [{"pid": "ue80686b", "order": 0, "text": "소형견은 하루 30분, 활동량이 많은 중대형견은 하루 1~2시간 산책이 권장된다. 산책 시간보다 냄새를 맡게 해 주는 시간이 더 중요하다.", "charLen": 77}, {"pid": "u308a26a", "order": 1, "text": "노즈워크는 후각을 쓰게 해 짧은 시간에도 에너지를 많이 소모시킨다. 비 오는 날 실내에서 대신하기 좋은 놀이다.", "charLen": 62}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-12-2", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-12-2", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-12-2", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://dogpages.tistory.com/57", "url": "https://dogpages.tistory.com/57", "title": "여름·겨울 산책 주의", "paragraphs": [{"pid": "ufa017a6", "order": 0, "text": "한여름 아스팔트는 50도를 넘을 수 있어 발바닥 화상 위험이 크다. 손등을 바닥에 5초 대 보고 뜨거우면 산책 시간을 옮긴다.", "charLen": 70}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-12-3", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-12-3", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-12-3", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://www.youtube.com/watch?v=dogtrain01", "url": "https://www.youtube.com/watch?v=dogtrain01", "title": "기다려 훈련 3단계", "paragraphs": [{"pid": "ud4efdd2", "order": 0, "text": "기다려 훈련은 1초부터 시작해 성공할 때마다 시간을 늘린다. 보상은 행동 직후 2초 안에 줘야 강아지가 무엇을 칭찬받는지 이해한다.", "charLen": 73}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-12-4", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-12-4", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-12-4", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://cafe.naver.com/dogcafe/50213", "url": "https://cafe.naver.com/dogcafe/50213", "title": "분리불안 고민", "paragraphs": [{"pid": "u9af5c6b", "order": 0, "text": "분리불안이 있는 강아지는 외출 준비 행동에 무뎌지게 하는 연습이 효과적이다. 열쇠를 들었다 내려놓기를 반복해 신호의 의미를 줄인다.", "charLen": 73}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-12-5", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-12-5", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-12-5", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}]}'::jsonb, TIMESTAMP '2026-10-11 04:58:00', TIMESTAMP '2026-10-11 04:59:00' + interval '21 days');
INSERT INTO session_raw_payloads (session_id, user_id, payload, received_at, expires_at) VALUES (13, 9, '{"kind": "rbc-session", "bundleVersion": 1, "session": {"sessionId": "seed-13", "tester": {"testId": "seed-user-9"}, "startedAt": "2026-10-10T05:57:00+09:00", "endedAt": "2026-10-10T07:09:00+09:00", "stopReason": "user", "focusMs": 2160000, "searchQuery": null, "tickMs": 150}, "pages": [{"meta": {"pageId": "https://docs.spring.io/spring-boot/reference/testing/index.html", "url": "https://docs.spring.io/spring-boot/reference/testing/index.html", "title": "Spring Boot 테스트", "paragraphs": [{"pid": "u48dbe29", "order": 0, "text": "SpringBootTest 는 전체 컨텍스트를 띄워 느리지만 실제와 가깝다. 컨트롤러만 확인할 때는 MockMvc 로 HTTP 요청과 응답을 검증한다.", "charLen": 84}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-13-0", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-13-0", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-13-0", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://velog.io/@devhan/testcontainers", "url": "https://velog.io/@devhan/testcontainers", "title": "Testcontainers 로 DB 테스트", "paragraphs": [{"pid": "u9ef74cd", "order": 0, "text": "H2 와 운영 DB 의 문법 차이 때문에 테스트는 통과하고 운영에서 깨지는 일이 있다. Testcontainers 로 실제 PostgreSQL 을 띄우면 이런 차이를 줄일 수 있다.", "charLen": 101}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-13-1", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-13-1", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-13-1", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://docs.spring.io/spring-data/jpa/reference/jpa/query-methods.html", "url": "https://docs.spring.io/spring-data/jpa/reference/jpa/query-methods.html", "title": "Spring Data JPA 쿼리 메서드", "paragraphs": [{"pid": "uf6cfd4a", "order": 0, "text": "Spring Data JPA 는 메서드 이름으로 쿼리를 만든다. findByUserIdAndDeletedAtIsNull 처럼 조건을 이어 쓰면 where 절이 자동으로 생성된다.", "charLen": 99}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-13-2", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-13-2", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-13-2", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://velog.io/@devhan/jpa-n-plus-1", "url": "https://velog.io/@devhan/jpa-n-plus-1", "title": "JPA N+1 문제 정리", "paragraphs": [{"pid": "udabe65c", "order": 0, "text": "연관 엔티티를 지연 로딩하면 목록을 조회할 때 쿼리가 N+1 번 나갈 수 있다. 페치 조인이나 EntityGraph 로 한 번에 가져오면 해결된다.", "charLen": 82}, {"pid": "u6d0801a", "order": 1, "text": "hibernate.default_batch_fetch_size 를 설정하면 지연 로딩 쿼리를 IN 절로 묶어 보내서 N+1 을 크게 줄일 수 있다.", "charLen": 82}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-13-3", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-13-3", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-13-3", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://techblog.woowahan.com/2711", "url": "https://techblog.woowahan.com/2711", "title": "JWT 토큰 갱신 전략", "paragraphs": [{"pid": "uf3cd4f4", "order": 0, "text": "리프레시 토큰은 재사용을 막기 위해 사용할 때마다 새로 발급하는 회전 방식이 안전하다. 탈취된 토큰이 재사용되면 해당 계열 전체를 폐기한다.", "charLen": 78}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-13-4", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-13-4", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-13-4", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://stackoverflow.com/questions/27726066", "url": "https://stackoverflow.com/questions/27726066", "title": "JWT vs session", "paragraphs": [{"pid": "u91988db", "order": 0, "text": "JWT 는 서버가 상태를 저장하지 않아 확장에 유리하지만, 즉시 로그아웃 처리가 어렵다. 그래서 만료 시간을 짧게 두고 리프레시 토큰을 함께 쓴다.", "charLen": 82}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-13-5", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-13-5", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-13-5", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}]}'::jsonb, TIMESTAMP '2026-10-10 07:09:00', TIMESTAMP '2026-10-10 07:10:00' + interval '21 days');
INSERT INTO session_raw_payloads (session_id, user_id, payload, received_at, expires_at) VALUES (14, 1, '{"kind": "rbc-session", "bundleVersion": 1, "session": {"sessionId": "seed-14", "tester": {"testId": "seed-user-1"}, "startedAt": "2026-10-15T20:24:00+09:00", "endedAt": "2026-10-15T20:53:00+09:00", "stopReason": "user", "focusMs": 870000, "searchQuery": null, "tickMs": 150}, "pages": [{"meta": {"pageId": "https://blog.naver.com/ballpark/223777", "url": "https://blog.naver.com/ballpark/223777", "title": "잠실 직관 좌석 추천", "paragraphs": [{"pid": "u7e8c057", "order": 0, "text": "잠실은 1루가 홈팀 응원석인 날이 많다. 응원을 즐기려면 내야 응원석, 경기를 편하게 보려면 중앙 테이블석이 좋다.", "charLen": 64}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-14-0", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-14-0", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-14-0", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://cafe.naver.com/kbofan/301122", "url": "https://cafe.naver.com/kbofan/301122", "title": "야구장 먹거리", "paragraphs": [{"pid": "u101ebf3", "order": 0, "text": "야구장 먹거리는 경기 시작 전에 사 두는 게 좋다. 5회 이후엔 줄이 길어져 이닝을 놓치기 쉽다.", "charLen": 54}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-14-1", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-14-1", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-14-1", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://sports.news.naver.com/kbaseball/news/read?oid=001&aid=0014", "url": "https://sports.news.naver.com/kbaseball/news/read?oid=001&aid=0014", "title": "OPS 로 보는 타자", "paragraphs": [{"pid": "u5b30ec9", "order": 0, "text": "OPS 는 출루율과 장타율을 더한 값으로, 0.900 을 넘으면 리그 정상급 타자로 본다. 타율보다 득점 기여를 더 잘 보여 준다.", "charLen": 73}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-14-2", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-14-2", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-14-2", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://www.yna.co.kr/view/AKR20261012000100007", "url": "https://www.yna.co.kr/view/AKR20261012000100007", "title": "올해 타격왕 경쟁", "paragraphs": [{"pid": "ue080cb0", "order": 0, "text": "타격왕은 규정 타석(경기 수 × 3.1)을 채운 타자 중 타율이 가장 높은 선수에게 돌아간다. 막판 결장으로 규정 타석을 못 채우면 순위에서 빠진다.", "charLen": 83}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-14-3", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-14-3", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-14-3", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://namu.wiki/w/WAR", "url": "https://namu.wiki/w/WAR", "title": "WAR 이란", "paragraphs": [{"pid": "u47516b1", "order": 0, "text": "WAR 은 대체 선수보다 팀 승리를 몇 번 더 만들었는지 나타낸다. 포지션과 구장 차이를 보정해서 선수끼리 비교할 때 많이 쓴다.", "charLen": 72}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-14-4", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-14-4", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-14-4", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://mlbpark.donga.com/mp/b.php?b=kbotown&id=2026101500", "url": "https://mlbpark.donga.com/mp/b.php?b=kbotown&id=2026101500", "title": "선발 이닝 수 논쟁", "paragraphs": [{"pid": "u602ea36", "order": 0, "text": "선발 투수가 6이닝 이상을 꾸준히 던져 주면 불펜 소모가 줄어 시즌 후반 순위 싸움에서 큰 차이가 난다.", "charLen": 58}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-14-5", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-14-5", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-14-5", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://www.chosun.com/sports/baseball/2026/10/14/", "url": "https://www.chosun.com/sports/baseball/2026/10/14/", "title": "피치클록 도입 효과", "paragraphs": [{"pid": "u17b1782", "order": 0, "text": "피치 클록 도입 뒤 경기 시간이 평균 20분 가까이 줄었다. 투수는 주자가 없을 때 정해진 시간 안에 투구해야 한다.", "charLen": 65}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-14-6", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-14-6", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-14-6", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}]}'::jsonb, TIMESTAMP '2026-10-15 20:53:00', TIMESTAMP '2026-10-15 20:54:00' + interval '21 days');
INSERT INTO session_raw_payloads (session_id, user_id, payload, received_at, expires_at) VALUES (15, 10, '{"kind": "rbc-session", "bundleVersion": 1, "session": {"sessionId": "seed-15", "tester": {"testId": "seed-user-10"}, "startedAt": "2026-10-11T23:48:00+09:00", "endedAt": "2026-10-12T00:30:00+09:00", "stopReason": "user", "focusMs": 1260000, "searchQuery": null, "tickMs": 150}, "pages": [{"meta": {"pageId": "https://health.chosun.com/site/data/html_dir/2026/10/20/", "url": "https://health.chosun.com/site/data/html_dir/2026/10/20/", "title": "겨울철 건조증", "paragraphs": [{"pid": "u3e3e4ac", "order": 0, "text": "겨울철 실내 습도는 40~60% 가 적당하다. 가습기를 쓸 때는 매일 물을 갈고 주 1회 이상 세척해야 세균 번식을 막는다.", "charLen": 69}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-15-0", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-15-0", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-15-0", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://www.yna.co.kr/view/AKR20261021000300017", "url": "https://www.yna.co.kr/view/AKR20261021000300017", "title": "독감 예방접종 시작", "paragraphs": [{"pid": "u33b8503", "order": 0, "text": "독감 예방접종은 항체가 생기기까지 2주 정도 걸려 10~11월에 맞는 것이 좋다. 65세 이상과 어린이는 무료로 맞을 수 있다.", "charLen": 71}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-15-1", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-15-1", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-15-1", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://www.hankyung.com/article/2026101820001", "url": "https://www.hankyung.com/article/2026101820001", "title": "난방비 아끼는 법", "paragraphs": [{"pid": "uc020c59", "order": 0, "text": "보일러를 완전히 끄기보다 외출 모드로 두는 편이 난방비가 덜 든다. 다시 데우는 데 드는 에너지가 더 크기 때문이다.", "charLen": 65}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-15-2", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-15-2", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-15-2", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://blog.naver.com/homecare/224010", "url": "https://blog.naver.com/homecare/224010", "title": "뽁뽁이와 문풍지", "paragraphs": [{"pid": "u868c7b1", "order": 0, "text": "창문에 단열 에어캡을 붙이고 문틈에 문풍지를 대면 실내 온도를 2~3도 지킬 수 있다. 결로가 생기면 자주 환기한다.", "charLen": 65}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-15-3", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-15-3", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-15-3", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://snowtrip.tistory.com/12", "url": "https://snowtrip.tistory.com/12", "title": "스키장 처음 갈 때", "paragraphs": [{"pid": "u874925f", "order": 0, "text": "스키를 처음 탄다면 첫날은 강습을 받고 초보 코스에서 멈추는 법부터 익히는 것이 안전하다. 리프트 시즌권보다 일일권이 낫다.", "charLen": 69}, {"pid": "u725db5d", "order": 1, "text": "스키장 옷은 땀을 빼는 속옷, 보온 중간층, 방수 겉옷으로 겹쳐 입어야 한다. 면 소재는 땀이 식으며 체온을 빼앗는다.", "charLen": 66}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-15-4", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-15-4", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-15-4", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://www.youtube.com/watch?v=skibasic02", "url": "https://www.youtube.com/watch?v=skibasic02", "title": "스키 A자 자세", "paragraphs": [{"pid": "u8e6352d", "order": 0, "text": "A자 자세는 스키 앞쪽을 모으고 뒤를 벌려 속도를 줄이는 기본 제동 자세다. 무릎을 살짝 굽혀야 넘어지지 않는다.", "charLen": 63}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-15-5", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-15-5", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-15-5", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}]}'::jsonb, TIMESTAMP '2026-10-12 00:30:00', TIMESTAMP '2026-10-12 00:31:00' + interval '21 days');
INSERT INTO session_raw_payloads (session_id, user_id, payload, received_at, expires_at) VALUES (16, 11, '{"kind": "rbc-session", "bundleVersion": 1, "session": {"sessionId": "seed-16", "tester": {"testId": "seed-user-11"}, "startedAt": "2026-10-24T21:14:00+09:00", "endedAt": "2026-10-24T21:43:00+09:00", "stopReason": "user", "focusMs": 870000, "searchQuery": null, "tickMs": 150}, "pages": [{"meta": {"pageId": "https://blog.naver.com/catlover/223001", "url": "https://blog.naver.com/catlover/223001", "title": "고양이 물 잘 먹이는 법", "paragraphs": [{"pid": "u1639fc1", "order": 0, "text": "고양이 음수량은 체중 1kg 당 하루 약 40~50ml 가 권장된다. 건사료만 먹는 고양이는 물이 부족해지기 쉬워서 습식 사료를 섞어 주는 게 좋다.", "charLen": 83}, {"pid": "u40d0c59", "order": 1, "text": "흐르는 물을 좋아하는 고양이가 많아 자동 급수기(정수기)를 두면 음수량이 눈에 띄게 늘어난다. 필터는 2~4주마다 갈아 주는 것이 위생적이다.", "charLen": 79}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-16-0", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-16-0", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-16-0", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://namu.wiki/w/고양이/건강", "url": "https://namu.wiki/w/고양이/건강", "title": "고양이 건강 관리", "paragraphs": [{"pid": "ub77e414", "order": 0, "text": "물을 적게 마시는 습관이 오래 가면 신장 질환과 방광염 위험이 높아진다. 노령묘는 6개월마다 혈액 검사로 신장 수치를 확인하는 편이 안전하다.", "charLen": 79}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-16-1", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-16-1", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-16-1", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://cafe.naver.com/ilovecat/88120", "url": "https://cafe.naver.com/ilovecat/88120", "title": "모래 추천 받아요", "paragraphs": [{"pid": "u6ba03d9", "order": 0, "text": "벤토나이트 모래는 응고력이 좋아 치우기 쉽지만 먼지가 날 수 있다. 두부 모래는 먼지가 적고 변기에 버릴 수 있다는 장점이 있다.", "charLen": 72}, {"pid": "uc87bba4", "order": 1, "text": "화장실 개수는 고양이 수보다 하나 더 많게 두는 것이 기본이다. 여러 마리를 키우면 서로 다른 방에 나눠 두어야 스트레스가 줄어든다.", "charLen": 74}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-16-2", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-16-2", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-16-2", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}]}'::jsonb, TIMESTAMP '2026-10-24 21:43:00', TIMESTAMP '2026-10-24 21:44:00' + interval '21 days');
INSERT INTO session_raw_payloads (session_id, user_id, payload, received_at, expires_at) VALUES (17, 1, '{"kind": "rbc-session", "bundleVersion": 1, "session": {"sessionId": "seed-17", "tester": {"testId": "seed-user-1"}, "startedAt": "2026-10-15T20:49:00+09:00", "endedAt": "2026-10-15T21:29:00+09:00", "stopReason": "user", "focusMs": 1200000, "searchQuery": null, "tickMs": 150}, "pages": [{"meta": {"pageId": "https://blog.naver.com/doglog/310442", "url": "https://blog.naver.com/doglog/310442", "title": "강아지 산책 시간 정하기", "paragraphs": [{"pid": "ue80686b", "order": 0, "text": "소형견은 하루 30분, 활동량이 많은 중대형견은 하루 1~2시간 산책이 권장된다. 산책 시간보다 냄새를 맡게 해 주는 시간이 더 중요하다.", "charLen": 77}, {"pid": "u308a26a", "order": 1, "text": "노즈워크는 후각을 쓰게 해 짧은 시간에도 에너지를 많이 소모시킨다. 비 오는 날 실내에서 대신하기 좋은 놀이다.", "charLen": 62}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-17-0", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-17-0", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-17-0", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://dogpages.tistory.com/57", "url": "https://dogpages.tistory.com/57", "title": "여름·겨울 산책 주의", "paragraphs": [{"pid": "ufa017a6", "order": 0, "text": "한여름 아스팔트는 50도를 넘을 수 있어 발바닥 화상 위험이 크다. 손등을 바닥에 5초 대 보고 뜨거우면 산책 시간을 옮긴다.", "charLen": 70}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-17-1", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-17-1", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-17-1", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://www.youtube.com/watch?v=dogtrain01", "url": "https://www.youtube.com/watch?v=dogtrain01", "title": "기다려 훈련 3단계", "paragraphs": [{"pid": "ud4efdd2", "order": 0, "text": "기다려 훈련은 1초부터 시작해 성공할 때마다 시간을 늘린다. 보상은 행동 직후 2초 안에 줘야 강아지가 무엇을 칭찬받는지 이해한다.", "charLen": 73}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-17-2", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-17-2", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-17-2", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://cafe.naver.com/dogcafe/50213", "url": "https://cafe.naver.com/dogcafe/50213", "title": "분리불안 고민", "paragraphs": [{"pid": "u9af5c6b", "order": 0, "text": "분리불안이 있는 강아지는 외출 준비 행동에 무뎌지게 하는 연습이 효과적이다. 열쇠를 들었다 내려놓기를 반복해 신호의 의미를 줄인다.", "charLen": 73}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-17-3", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-17-3", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-17-3", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}]}'::jsonb, TIMESTAMP '2026-10-15 21:29:00', TIMESTAMP '2026-10-15 21:30:00' + interval '21 days');
INSERT INTO session_raw_payloads (session_id, user_id, payload, received_at, expires_at) VALUES (18, 12, '{"kind": "rbc-session", "bundleVersion": 1, "session": {"sessionId": "seed-18", "tester": {"testId": "seed-user-12"}, "startedAt": "2026-10-28T08:45:00+09:00", "endedAt": "2026-10-28T09:56:00+09:00", "stopReason": "user", "focusMs": 2130000, "searchQuery": null, "tickMs": 150}, "pages": [{"meta": {"pageId": "https://docs.spring.io/spring-data/jpa/reference/jpa/query-methods.html", "url": "https://docs.spring.io/spring-data/jpa/reference/jpa/query-methods.html", "title": "Spring Data JPA 쿼리 메서드", "paragraphs": [{"pid": "uf6cfd4a", "order": 0, "text": "Spring Data JPA 는 메서드 이름으로 쿼리를 만든다. findByUserIdAndDeletedAtIsNull 처럼 조건을 이어 쓰면 where 절이 자동으로 생성된다.", "charLen": 99}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-18-0", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-18-0", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-18-0", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://velog.io/@devhan/jpa-n-plus-1", "url": "https://velog.io/@devhan/jpa-n-plus-1", "title": "JPA N+1 문제 정리", "paragraphs": [{"pid": "udabe65c", "order": 0, "text": "연관 엔티티를 지연 로딩하면 목록을 조회할 때 쿼리가 N+1 번 나갈 수 있다. 페치 조인이나 EntityGraph 로 한 번에 가져오면 해결된다.", "charLen": 82}, {"pid": "u6d0801a", "order": 1, "text": "hibernate.default_batch_fetch_size 를 설정하면 지연 로딩 쿼리를 IN 절로 묶어 보내서 N+1 을 크게 줄일 수 있다.", "charLen": 82}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-18-1", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-18-1", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-18-1", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://techblog.woowahan.com/2711", "url": "https://techblog.woowahan.com/2711", "title": "JWT 토큰 갱신 전략", "paragraphs": [{"pid": "uf3cd4f4", "order": 0, "text": "리프레시 토큰은 재사용을 막기 위해 사용할 때마다 새로 발급하는 회전 방식이 안전하다. 탈취된 토큰이 재사용되면 해당 계열 전체를 폐기한다.", "charLen": 78}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-18-2", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-18-2", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-18-2", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://stackoverflow.com/questions/27726066", "url": "https://stackoverflow.com/questions/27726066", "title": "JWT vs session", "paragraphs": [{"pid": "u91988db", "order": 0, "text": "JWT 는 서버가 상태를 저장하지 않아 확장에 유리하지만, 즉시 로그아웃 처리가 어렵다. 그래서 만료 시간을 짧게 두고 리프레시 토큰을 함께 쓴다.", "charLen": 82}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-18-3", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-18-3", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-18-3", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}]}'::jsonb, TIMESTAMP '2026-10-28 09:56:00', TIMESTAMP '2026-10-28 09:57:00' + interval '21 days');
INSERT INTO session_raw_payloads (session_id, user_id, payload, received_at, expires_at) VALUES (19, 13, '{"kind": "rbc-session", "bundleVersion": 1, "session": {"sessionId": "seed-19", "tester": {"testId": "seed-user-13"}, "startedAt": "2026-10-27T05:41:00+09:00", "endedAt": "2026-10-27T07:01:00+09:00", "stopReason": "user", "focusMs": 2400000, "searchQuery": null, "tickMs": 150}, "pages": [{"meta": {"pageId": "https://sports.news.naver.com/kbaseball/news/read?oid=001&aid=0014", "url": "https://sports.news.naver.com/kbaseball/news/read?oid=001&aid=0014", "title": "OPS 로 보는 타자", "paragraphs": [{"pid": "u5b30ec9", "order": 0, "text": "OPS 는 출루율과 장타율을 더한 값으로, 0.900 을 넘으면 리그 정상급 타자로 본다. 타율보다 득점 기여를 더 잘 보여 준다.", "charLen": 73}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-19-0", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-19-0", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-19-0", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://www.yna.co.kr/view/AKR20261012000100007", "url": "https://www.yna.co.kr/view/AKR20261012000100007", "title": "올해 타격왕 경쟁", "paragraphs": [{"pid": "ue080cb0", "order": 0, "text": "타격왕은 규정 타석(경기 수 × 3.1)을 채운 타자 중 타율이 가장 높은 선수에게 돌아간다. 막판 결장으로 규정 타석을 못 채우면 순위에서 빠진다.", "charLen": 83}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-19-1", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-19-1", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-19-1", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://namu.wiki/w/WAR", "url": "https://namu.wiki/w/WAR", "title": "WAR 이란", "paragraphs": [{"pid": "u47516b1", "order": 0, "text": "WAR 은 대체 선수보다 팀 승리를 몇 번 더 만들었는지 나타낸다. 포지션과 구장 차이를 보정해서 선수끼리 비교할 때 많이 쓴다.", "charLen": 72}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-19-2", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-19-2", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-19-2", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://mlbpark.donga.com/mp/b.php?b=kbotown&id=2026101500", "url": "https://mlbpark.donga.com/mp/b.php?b=kbotown&id=2026101500", "title": "선발 이닝 수 논쟁", "paragraphs": [{"pid": "u602ea36", "order": 0, "text": "선발 투수가 6이닝 이상을 꾸준히 던져 주면 불펜 소모가 줄어 시즌 후반 순위 싸움에서 큰 차이가 난다.", "charLen": 58}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-19-3", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-19-3", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-19-3", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://www.chosun.com/sports/baseball/2026/10/14/", "url": "https://www.chosun.com/sports/baseball/2026/10/14/", "title": "피치클록 도입 효과", "paragraphs": [{"pid": "u17b1782", "order": 0, "text": "피치 클록 도입 뒤 경기 시간이 평균 20분 가까이 줄었다. 투수는 주자가 없을 때 정해진 시간 안에 투구해야 한다.", "charLen": 65}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-19-4", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-19-4", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-19-4", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}]}'::jsonb, TIMESTAMP '2026-10-27 07:01:00', TIMESTAMP '2026-10-27 07:02:00' + interval '21 days');
INSERT INTO session_raw_payloads (session_id, user_id, payload, received_at, expires_at) VALUES (20, 1, '{"kind": "rbc-session", "bundleVersion": 1, "session": {"sessionId": "seed-20", "tester": {"testId": "seed-user-1"}, "startedAt": "2026-10-10T21:01:00+09:00", "endedAt": "2026-10-10T22:19:00+09:00", "stopReason": "user", "focusMs": 2340000, "searchQuery": null, "tickMs": 150}, "pages": [{"meta": {"pageId": "https://www.hankyung.com/article/2026101820001", "url": "https://www.hankyung.com/article/2026101820001", "title": "난방비 아끼는 법", "paragraphs": [{"pid": "uc020c59", "order": 0, "text": "보일러를 완전히 끄기보다 외출 모드로 두는 편이 난방비가 덜 든다. 다시 데우는 데 드는 에너지가 더 크기 때문이다.", "charLen": 65}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-20-0", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-20-0", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-20-0", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://blog.naver.com/homecare/224010", "url": "https://blog.naver.com/homecare/224010", "title": "뽁뽁이와 문풍지", "paragraphs": [{"pid": "u868c7b1", "order": 0, "text": "창문에 단열 에어캡을 붙이고 문틈에 문풍지를 대면 실내 온도를 2~3도 지킬 수 있다. 결로가 생기면 자주 환기한다.", "charLen": 65}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-20-1", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-20-1", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-20-1", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://snowtrip.tistory.com/12", "url": "https://snowtrip.tistory.com/12", "title": "스키장 처음 갈 때", "paragraphs": [{"pid": "u874925f", "order": 0, "text": "스키를 처음 탄다면 첫날은 강습을 받고 초보 코스에서 멈추는 법부터 익히는 것이 안전하다. 리프트 시즌권보다 일일권이 낫다.", "charLen": 69}, {"pid": "u725db5d", "order": 1, "text": "스키장 옷은 땀을 빼는 속옷, 보온 중간층, 방수 겉옷으로 겹쳐 입어야 한다. 면 소재는 땀이 식으며 체온을 빼앗는다.", "charLen": 66}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-20-2", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-20-2", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-20-2", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}, {"meta": {"pageId": "https://www.youtube.com/watch?v=skibasic02", "url": "https://www.youtube.com/watch?v=skibasic02", "title": "스키 A자 자세", "paragraphs": [{"pid": "u8e6352d", "order": 0, "text": "A자 자세는 스키 앞쪽을 모으고 뒤를 벌려 속도를 줄이는 기본 제동 자세다. 무릎을 살짝 굽혀야 넘어지지 않는다.", "charLen": 63}]}, "timeline": [{"type": "tick", "t": 0, "segId": "seg-20-3", "centerPid": null, "cursorPid": null, "scrollY": 0, "vis": []}, {"type": "tick", "t": 150, "segId": "seg-20-3", "centerPid": null, "cursorPid": null, "scrollY": 120, "vis": []}, {"type": "tick", "t": 300, "segId": "seg-20-3", "centerPid": null, "cursorPid": null, "scrollY": 240, "vis": []}]}]}'::jsonb, TIMESTAMP '2026-10-10 22:19:00', TIMESTAMP '2026-10-10 22:20:00' + interval '21 days');
