INSERT INTO community_bookmarks (id, user_id, save_type, target_type, selection_key, source_mindmap_id, target_ids, snapshot, saved_at) VALUES (1, 1, 'MINI_MINDMAP', 'NODE', 'c5a042165b91f344bc40646cb5ff9db6b41c02b1daf874278404c779186ecb14', 5, '[7]'::jsonb, '{"title": "Saved community mindmap", "hashtags": [{"hashtagId": 47, "ownerId": 5, "name": "사료"}, {"hashtagId": 48, "ownerId": 5, "name": "훈련"}], "nodes": [{"nodeId": 7, "label": "분리불안 고민", "sourceUrl": "https://cafe.naver.com/dogcafe/50213", "content": "분리불안이 있는 강아지는 외출 준비 행동에 무뎌지게 하는 연습이 효과적이다. 열쇠를 들었다 내려놓기를 반복해", "visibilityScope": "CONTENT"}], "edges": [{"from": "tag:47", "to": "node:7"}, {"from": "tag:48", "to": "node:7"}]}'::jsonb, (TIMESTAMP '2026-10-28 12:07:00') AT TIME ZONE 'Asia/Seoul');
INSERT INTO community_bookmarks (id, user_id, save_type, target_type, selection_key, source_mindmap_id, target_ids, snapshot, saved_at) VALUES (2, 4, 'MINI_MINDMAP', 'NODE', '2b92ecd529f72b261c0b3822e18f7d63c1c1ad1f65135f23e3dc0496683e6bf2', 5, '[8]'::jsonb, '{"title": "Saved community mindmap", "hashtags": [{"hashtagId": 47, "ownerId": 5, "name": "사료"}, {"hashtagId": 48, "ownerId": 5, "name": "훈련"}], "nodes": [{"nodeId": 8, "label": "강아지가 먹으면 안 되는 음식", "sourceUrl": "https://namu.wiki/w/개/먹이", "content": "포도와 건포도, 초콜릿, 양파, 자일리톨은 소량으로도 강아지에게 위험하다. 먹었다면 바로 동물병원에 연락한다", "visibilityScope": "CONTENT"}], "edges": [{"from": "tag:47", "to": "node:8"}, {"from": "tag:48", "to": "node:8"}]}'::jsonb, (TIMESTAMP '2026-10-26 01:56:00') AT TIME ZONE 'Asia/Seoul');
INSERT INTO community_bookmarks (id, user_id, save_type, target_type, selection_key, source_mindmap_id, target_ids, snapshot, saved_at) VALUES (3, 4, 'MINI_MINDMAP', 'NODE', 'b06fd31618cbe41774d217884e66dc63ef0160059c21ed24adebc70afc765a74', 6, '[12]'::jsonb, '{"title": "Saved community mindmap", "hashtags": [{"hashtagId": 52, "ownerId": 6, "name": "투수"}, {"hashtagId": 53, "ownerId": 6, "name": "직관"}], "nodes": [{"nodeId": 12, "label": "선발 이닝 수 논쟁", "sourceUrl": "https://mlbpark.donga.com/mp/b.php?b=kbotown&id=2026101500", "content": "선발 투수가 6이닝 이상을 꾸준히 던져 주면 불펜 소모가 줄어 시즌 후반 순위 싸움에서 큰 차이가 난다.", "visibilityScope": "CONTENT"}], "edges": [{"from": "tag:52", "to": "node:12"}, {"from": "tag:53", "to": "node:12"}]}'::jsonb, (TIMESTAMP '2026-10-28 19:14:00') AT TIME ZONE 'Asia/Seoul');
INSERT INTO community_bookmarks (id, user_id, save_type, target_type, selection_key, source_mindmap_id, target_ids, snapshot, saved_at) VALUES (4, 6, 'MINI_MINDMAP', 'NODE', '21e68df7fc1eb25b759087c79dacd576bc455c39bf20537b2c0dec1af4c67b36', 8, '[24]'::jsonb, '{"title": "Saved community mindmap", "hashtags": [{"hashtagId": 62, "ownerId": 8, "name": "사료"}, {"hashtagId": 63, "ownerId": 8, "name": "훈련"}], "nodes": [{"nodeId": 24, "label": "강아지가 먹으면 안 되는 음식", "sourceUrl": "https://namu.wiki/w/개/먹이", "content": "포도와 건포도, 초콜릿, 양파, 자일리톨은 소량으로도 강아지에게 위험하다. 먹었다면 바로 동물병원에 연락한다", "visibilityScope": "CONTENT"}], "edges": [{"from": "tag:62", "to": "node:24"}, {"from": "tag:63", "to": "node:24"}]}'::jsonb, (TIMESTAMP '2026-10-29 20:24:00') AT TIME ZONE 'Asia/Seoul');
INSERT INTO community_bookmarks (id, user_id, save_type, target_type, selection_key, source_mindmap_id, target_ids, snapshot, saved_at) VALUES (5, 6, 'MINI_MINDMAP', 'NODE', '9e960f96c5965c594c77617d7984e059118735523f29ab7e860b1dd6f6639945', 9, '[29]'::jsonb, '{"title": "Saved community mindmap", "hashtags": [{"hashtagId": 67, "ownerId": 9, "name": "테스트"}, {"hashtagId": 68, "ownerId": 9, "name": "JPA"}], "nodes": [{"nodeId": 29, "label": "Testcontainers 로 DB 테스트", "sourceUrl": "https://velog.io/@devhan/testcontainers", "content": "H2 와 운영 DB 의 문법 차이 때문에 테스트는 통과하고 운영에서 깨지는 일이 있다. Testcontain", "visibilityScope": "CONTENT"}], "edges": [{"from": "tag:67", "to": "node:29"}, {"from": "tag:68", "to": "node:29"}]}'::jsonb, (TIMESTAMP '2026-10-30 01:57:00') AT TIME ZONE 'Asia/Seoul');
INSERT INTO community_bookmarks (id, user_id, save_type, target_type, selection_key, source_mindmap_id, target_ids, snapshot, saved_at) VALUES (6, 7, 'MINI_MINDMAP', 'NODE', '47b640953793996ef05a6cf92e2a2aaadf002f4752b03c48bf971fb398151c94', 9, '[30]'::jsonb, '{"title": "Saved community mindmap", "hashtags": [{"hashtagId": 67, "ownerId": 9, "name": "테스트"}, {"hashtagId": 68, "ownerId": 9, "name": "JPA"}], "nodes": [{"nodeId": 30, "label": "JPA N+1 문제 정리", "sourceUrl": "https://velog.io/@devhan/jpa-n-plus-1", "content": "연관 엔티티를 지연 로딩하면 목록을 조회할 때 쿼리가 N+1 번 나갈 수 있다. 페치 조인이나 EntityG", "visibilityScope": "CONTENT"}], "edges": [{"from": "tag:67", "to": "node:30"}, {"from": "tag:68", "to": "node:30"}]}'::jsonb, (TIMESTAMP '2026-10-29 03:40:00') AT TIME ZONE 'Asia/Seoul');
INSERT INTO community_bookmarks (id, user_id, save_type, target_type, selection_key, source_mindmap_id, target_ids, snapshot, saved_at) VALUES (7, 8, 'MINI_MINDMAP', 'NODE', 'ee228180ecd2e53372dbedc36770343e0da1b5a3a16b4c6604a74b0034cf711b', 1, '[20]'::jsonb, '{"title": "Saved community mindmap", "hashtags": [{"hashtagId": 1, "ownerId": 1, "name": "놀이"}, {"hashtagId": 3, "ownerId": 1, "name": "음수량"}], "nodes": [{"nodeId": 20, "label": "고양이 물 잘 먹이는 법", "sourceUrl": "https://blog.naver.com/catlover/223001", "content": "고양이 음수량은 체중 1kg 당 하루 약 40~50ml 가 권장된다. 건사료만 먹는 고양이는 물이 부족해지기", "visibilityScope": "CONTENT"}], "edges": [{"from": "tag:1", "to": "node:20"}, {"from": "tag:3", "to": "node:20"}]}'::jsonb, (TIMESTAMP '2026-10-27 09:16:00') AT TIME ZONE 'Asia/Seoul');
INSERT INTO community_bookmarks (id, user_id, save_type, target_type, selection_key, source_mindmap_id, target_ids, snapshot, saved_at) VALUES (8, 9, 'MINI_MINDMAP', 'NODE', '7257edf08a9e0909c3960e054cf9b535ec9bd4b0b582095efeb6cf40161eae81', 8, '[25]'::jsonb, '{"title": "Saved community mindmap", "hashtags": [{"hashtagId": 62, "ownerId": 8, "name": "사료"}, {"hashtagId": 63, "ownerId": 8, "name": "훈련"}], "nodes": [{"nodeId": 25, "label": "강아지 산책 시간 정하기", "sourceUrl": "https://blog.naver.com/doglog/310442", "content": "소형견은 하루 30분, 활동량이 많은 중대형견은 하루 1~2시간 산책이 권장된다. 산책 시간보다 냄새를 맡게", "visibilityScope": "CONTENT"}], "edges": [{"from": "tag:62", "to": "node:25"}, {"from": "tag:63", "to": "node:25"}]}'::jsonb, (TIMESTAMP '2026-10-29 07:45:00') AT TIME ZONE 'Asia/Seoul');
INSERT INTO community_bookmarks (id, user_id, save_type, target_type, selection_key, source_mindmap_id, target_ids, snapshot, saved_at) VALUES (9, 10, 'MINI_MINDMAP', 'NODE', 'c85039b13d2d7b458987a2155a554a91ba8eabdf5c42f0bb3d9e0328a2df9890', 1, '[38]'::jsonb, '{"title": "Saved community mindmap", "hashtags": [{"hashtagId": 22, "ownerId": 1, "name": "투수"}, {"hashtagId": 23, "ownerId": 1, "name": "타격지표"}], "nodes": [{"nodeId": 38, "label": "피치클록 도입 효과", "sourceUrl": "https://www.chosun.com/sports/baseball/2026/10/14/", "content": "피치 클록 도입 뒤 경기 시간이 평균 20분 가까이 줄었다. 투수는 주자가 없을 때 정해진 시간 안에 투구해", "visibilityScope": "CONTENT"}], "edges": [{"from": "tag:22", "to": "node:38"}, {"from": "tag:23", "to": "node:38"}]}'::jsonb, (TIMESTAMP '2026-10-28 08:01:00') AT TIME ZONE 'Asia/Seoul');
