INSERT INTO community_bookmarks (id, user_id, save_type, target_type, selection_key, source_mindmap_id, target_ids, snapshot, saved_at) VALUES (11, 12, 'MINI_MINDMAP', 'NODE', '7e114b3d2400a50788175b5e4941978bdc1f6852d271481ff0821c43fe5c45c2', 7, '[16]'::jsonb, '{"title": "Saved community mindmap", "hashtags": [{"hashtagId": 57, "ownerId": 7, "name": "건강"}, {"hashtagId": 58, "ownerId": 7, "name": "스키"}], "nodes": [{"nodeId": 16, "label": "스키 A자 자세", "sourceUrl": "https://www.youtube.com/watch?v=skibasic02", "content": "A자 자세는 스키 앞쪽을 모으고 뒤를 벌려 속도를 줄이는 기본 제동 자세다. 무릎을 살짝 굽혀야 넘어지지 않", "visibilityScope": "CONTENT"}], "edges": [{"from": "tag:57", "to": "node:16"}, {"from": "tag:58", "to": "node:16"}]}'::jsonb, (TIMESTAMP '2026-10-27 00:20:00') AT TIME ZONE 'Asia/Seoul');
